pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: proportional to progress to discourage early fragmentation
    // but allow opening bins if it preserves space for future items.
    if is_new_bin {
        score += 15.0 + (progress * 40.0);
    } else {
        // Encourage filling bins that are already "tight" to maximize density.
        // We penalize high post_residual if the bin is already sparse.
        let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score += (post_residual as f64 * tightness * 0.5);

        // Lookahead heuristic: If the next item is large, avoid leaving small residuals
        // that are unlikely to fit future items.
        if next_item_size > 0 {
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 1.2;
            }
        }
    }

    // Global constraint: If this is the last fitting bin, prioritize it to avoid
    // the "new bin" penalty, unless the bin is very inefficient.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Soft constraint: Discourage excessive bin proliferation by penalizing
    // the creation of new bins when we have many open bins already.
    if is_new_bin {
        score += (open_bins_count as f64).powf(1.1) * 2.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // post_residual: 0 is perfect, high is bad.
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (gaps < 10, as items are >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead logic: if we can fit the next item, prioritize bins that keep a "good" residual for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that fit the next item perfectly (residual 0 after next item)
            let secondary_residual = post_residual - next_item_size;
            score -= (100.0 - secondary_residual as f64) * 0.5;
        } else {
            // Penalize bins that cannot fit the next item if we are running out of bins
            score += 20.0;
        }
    }

    // 3. Global state: balance load across open bins.
    // If this bin's residual is much higher than the mean, we are creating an imbalance.
    if (bin_residual as f64) > mean_residual {
        score += 10.0;
    }

    // 4. New bin management:
    // Only open a new bin if the current fit is terrible (post_residual > 40)
    // or if we have no other choice.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 && post_residual < 40 {
            score += 100.0; // Heavily penalize opening a new bin if a decent fit exists
        } else {
            score -= 10.0; // Otherwise, prefer opening a new bin to save space for larger future items
        }
    }

    // 5. Time horizon: as we approach the end of the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize creating "slivers" (very small residuals that are hard to fill)
    // We penalize residuals in the range [1, 9] heavily as they are rarely useful.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization: If next_item_size exists, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // Strong incentive to keep room for the next item
        } else {
            score += 15.0; // Penalty if this placement prevents the next item from fitting
        }
    }

    // 3. Global state awareness: If we have many open bins, prioritize tightening existing ones.
    // If open_bins_count is high, we want to prioritize filling the "tightest" bin possible.
    score += (open_bins_count as f64) * 2.0;

    // 4. Dynamic thresholding: Near the end of the stream, prioritize bin consolidation.
    if progress > 0.8 {
        score -= (mean_residual - post_residual as f64).abs();
    }

    // 5. Handling the "New Bin" case:
    // If bin_residual == bin_capacity, this is the score for opening a new bin.
    // We only want to open a new bin if the current fit is catastrophic (e.g., leaving a tiny sliver)
    // or if the current bin is nearly full and we need to save it for a larger future item.
    if bin_residual == bin_capacity {
        // Base cost to open a new bin is high to encourage reuse.
        score = 45.0;

        // If we are forced to create a tiny sliver in all existing bins, opening a new one is better.
        if fitting_bins_count > 0 {
            score += 40.0; 
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // The base strategy is Best-Fit Decreasing logic (minimizing post_residual).
    // We penalize bins that leave very small, unusable gaps (1-9) which are hard to fill.
    let gap_penalty = if post_residual > 0 && post_residual < 10 {
        25.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Use lookahead: if the next item is large, prioritize keeping the residual high.
    // If next_item_size is 0 (end of stream), we prioritize packing tightest.
    let lookahead_factor = if next_item_size > 0 {
        if post_residual < next_item_size {
            30.0 * (1.0 - progress)
        } else {
            -10.0 * (1.0 - progress)
        }
    } else {
        0.0
    };

    // Balance against the number of open bins to prevent unnecessary fragmentation.
    // As the stream progresses, prioritize closing bins (lower open_bins_count).
    let efficiency_pressure = (open_bins_count as f64) * 2.0 * progress;

    // New bin candidate logic:
    // If the bin is new, it has a high residual. We only choose it if the current
    // fitting options are extremely poor (i.e., would result in high gap_penalty).
    let mut score = post + gap_penalty + lookahead_factor + efficiency_pressure;

    if bin_residual == bin_capacity {
        // Strongly discourage opening a new bin unless the existing fitting bins
        // are all highly inefficient (high post_residual).
        score = 45.0 + (mean_residual * 0.5);

        // If no other bins can fit the item, opening a new bin is mandatory.
        if fitting_bins_count == 0 {
            score = -100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: Heavily penalize residuals that are too small to fit common items
    // (1-9) but too large to be considered "tight" packing.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64).sqrt();
    }

    // 2. Lookahead optimization: If the next item fits into the current post_residual,
    // reward this bin to encourage packing pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Open bin pressure: If this is an existing bin, penalize it if we have too many
    // open bins, forcing the algorithm to consolidate.
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * 2.0;
    }

    // 4. New bin thresholding: If this is a new bin (bin_residual == bin_capacity),
    // only choose it if the current fitting bins are extremely inefficient.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // High penalty for opening new bins when space is available
            score += 85.0 + (mean_residual * 0.5);
        }
    } else {
        // Reward bins that bring the residual closer to the global mean,
        // promoting uniform packing density.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 5. Finalize: Discourage empty space at the end of the stream
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that cannot fit typical items (10-30 range)
    // If post_residual is small but not zero, it's often wasted.
    if post_residual > 0 && post_residual < 15 {
        score += 40.0;
    }

    // 2. Aggressive Lookahead: If next_item_size fits in the post_residual, 
    // highly reward this bin to keep the packing tight.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0;
        // Further reward if it creates a "perfect" fit
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // 3. Prevent fragmentation: If this is the only bin that fits the current item, 
    // but the post_residual is very large, penalize it to encourage a new bin 
    // if the current state is early in the stream.
    if fitting_bins_count == 1 && post_residual > 60 {
        let progress = step_index as f64 / total_items as f64;
        score += 20.0 * (1.0 - progress);
    }

    // 4. Global balance: If this bin's residual is significantly better than the mean,
    // favor it to keep the average residual low across all bins.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 5. New Bin Logic: If calling for a new bin (bin_residual == bin_capacity),
    // set a baseline cost that makes it only attractive if existing bins are poor.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is 55.0. 
        // We reduce this cost if we are very early in the stream or if open_bins_count is low.
        score = 55.0 - (open_bins_count as f64 * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We naturally prefer smaller post_residual (Best Fit).

    // 2. Lookahead Integration: If next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the bin to prevent stranding the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 50.0 + (next_item_size - post_residual) as f64;
        }
    }

    // 3. New Bin Thresholding: Prevent opening new bins unless the current fit is extremely poor.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty based on global state.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score = 45.0; 

        // Dynamic scaling: As the stream progresses, it becomes more expensive to open new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;

        // If there are existing bins with very low residuals, penalize opening a new one further.
        if mean_residual < 20.0 {
            score += 15.0;
        }
    } else {
        // 4. Scarcity/Fitting Logic:
        // If this is the last bin that can fit the current item, reward it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }

        // 5. Fragmentation Avoidance:
        // Penalize residuals that are too small to fit any likely item (e.g., < 10), 
        // as they become "dead space".
        if post_residual < 10 && post_residual > 0 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize residues that are "nearly" useful for common item sizes
    // We want to avoid residues in the range [10, 20] which are too small for most items
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 * (20.0 - post_residual as f64) / 20.0;
    }

    // 2. Lookahead Logic: If the next item fits into the current post_residual, prioritize this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 35.0;
    }

    // 3. Fragmentation Control: Penalize bins that leave very small slivers
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. Harmonic Alignment: Reward bins that leave residues which are multiples of 25 (common packing target)
    if post_residual % 25 == 0 {
        score -= 15.0;
    }

    // 5. New Bin Threshold: If this is an empty bin, only pick it if we have too many open bins
    // or if the current best fitting bin is extremely poor (large penalty)
    if bin_residual == bin_capacity {
        if open_bins_count < 3 {
            score += 60.0; // Discourage opening new bins early
        } else {
            score += 20.0; // Moderately discourage, but allow if others are bad
        }
    }

    // 6. Density Coupling: Adjust based on the mean residual of existing bins
    // If our current bin's post_residual is better than the mean, favor it
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 7. Last Chance Constraint: If only one bin can fit the item, we must take it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Class Penalty: Penalize residuals that are small but not zero (dead space).
    // We favor "perfect fits" (post_residual == 0) and "large gaps" (which leave room for future items).
    if post_residual > 0 {
        // Penalty for creating "sliver" space: 1-9 is often unusable for large items.
        if post_residual < 10 {
            score += 50.0;
        }
        // Harmonic weighting: punish residuals that are small factors of capacity.
        score += (bin_capacity as f64) / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Logic: If the next item is large, favor keeping bins with enough space.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalty for stranding the next item if this bin could have been saved.
            score += 25.0;
        }
    }

    // 3. New Bin Thresholding: 
    // If this is a new bin (bin_residual == bin_capacity), make it expensive unless
    // existing bins are highly fragmented (mean_residual is low).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin
        score = 60.0;
        // If current bins are already very full, opening a new one is more attractive.
        if mean_residual < 20.0 {
            score -= 20.0;
        }
    }

    // 4. Fitting Constraint: 
    // If this is the only bin that fits, we must prioritize it unless it's a terrible fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Progression Scaling:
    // Toward the end of the stream, prioritize packing density over flexibility.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // A lower score indicates a more desirable bin choice.

    // 1. Base Score: The post-residual space.
    // Minimizing post_residual is the standard Best-Fit approach.
    let mut score = post_residual as f64;

    // 2. Penalty for creating "dead space" (small, unusable gaps).
    // If post_residual is between 1 and 9, it's highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead Logic: 
    // If we have a next item, check if it fits in the current post_residual.
    // If it fits perfectly or well, we prioritize this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.5;
        } else {
            // If the next item cannot fit, we penalize based on how much 
            // the current choice prevents future packing efficiency.
            score += 5.0;
        }
    }

    // 4. Global State: 
    // If this is the only bin that can fit the item, we are forced to pick it.
    // We heavily discount its score to make it the clear winner.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Dynamic Time Horizon:
    // As we reach the end of the stream, we become more conservative about 
    // opening new bins (penalizing the "new bin" candidate).
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin increases as we progress through the stream,
        // unless we have very few bins open.
        score += 40.0 * progress;
        score -= (open_bins_count as f64) * 0.5;
    }

    // 6. Mean Residual Balancing:
    // If this bin's residual is significantly better than the global mean,
    // we favor keeping it balanced.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual values that are likely to become "trapped"
    // (unusable space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Best-Fit/First-Fit Hybrid: Favor tight packing.
    // If we have many open bins, we prioritize closing gaps.
    score += (open_bins_count as f64) * 0.5;

    // 3. Lookahead Strategy: If the next item is large, avoid leaving small residuals now
    // that prevent the next item from fitting in this bin.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        }
    }

    // 4. New Bin Thresholding:
    // When evaluating a new bin (bin_residual == bin_capacity), make it expensive unless
    // all other options result in very poor packing (high post_residual).
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin, reduced by the number of bins already open
        // and the difficulty of fitting the current item into existing bins.
        score = 85.0 + (open_bins_count as f64 * 0.2);

        // If the item fits perfectly into a new bin (rare), lower the penalty.
        if item_size == bin_capacity {
            score -= 40.0;
        }
    } else {
        // Reward bins that have residuals close to the mean, promoting balanced fill rates.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= deviation * 0.1;
    }

    // 5. Urgency: As we approach the end of the stream, prioritize aggressive packing.
    let progress = step_index as f64 / total_items as f64;
    score *= (1.0 + progress * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating small, unusable gaps (The "Dead Space" avoidance)
    // If post_residual is small but > 0, it's often a bad fit unless it perfectly matches future items.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Harmonic Lookahead: reward fitting the item such that the post_residual
    // is a multiple of the next_item_size, effectively preparing for the next step.
    if next_item_size > 0 {
        let remainder = post_residual % next_item_size;
        // If the post_residual can perfectly accommodate the next item, heavily reward it.
        if remainder == 0 {
            score -= 30.0;
        } else {
            // Penalize based on how much space is wasted relative to the next item
            score += (remainder as f64) * 0.5;
        }
    }

    // 3. Pressure Management:
    // If we have many open bins, we want to consolidate (prefer smaller residuals).
    // If we have few open bins, we can be more flexible.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score += (open_bins_count as f64) * fill_ratio * 5.0;

    // 4. Threshold for opening new bins:
    // If the bin is new (bin_residual == bin_capacity), set a baseline cost to open a new bin.
    // This cost is modulated by how many bins are already open to prevent fragmentation.
    if bin_residual == bin_capacity {
        score = 25.0 + (open_bins_count as f64 * 0.5);
    }

    // 5. Fitting constraints:
    // If this is the last bin that can fit the item, prioritize it to avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Global progress adjustment:
