        score += (10.0 - post).powi(2) * 2.0;
    }

    // Lookahead logic: If the next item cannot fit in this post_residual,
    // we penalize the bin slightly to encourage saving space for future items.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 15.0 * (1.0 - progress);
    }

    // Dynamic thresholding: As we approach the end of the stream (progress -> 1.0),
    // we become more aggressive about filling existing bins (penalize new bins).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Discourage opening new bins unless the fit is extremely poor (large post_residual).
        // The penalty for a new bin grows as we reach the end of the stream.
        score += 40.0 + (progress * 60.0);
    } else {
        // If we are late in the stream, prioritize bins that are already open
        // to reduce the total count.
        score -= (progress * 20.0);
    }

    // Reward bins that keep the mean_residual high (maintaining flexibility).
    score += (mean_residual - post) * 0.5;

    // If this is the last chance to fit the item (only one bin can take it),
    // reduce the score significantly to prioritize fitting over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Harmonic classes logic.
    // The objective is to minimize post_residual (Best Fit) while penalizing "sliver" residuals
    // that are too small to fit common items (10-80 range).

    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize residuals that fall in "unusable" ranges for future items.
    // If post_residual is between 1 and 9, it is extremely unlikely to fit another item.
    // We treat these as "dead space" penalties.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // significantly reward this placement (prioritize Best Fit + Lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Bonus for creating a "perfect fit" for the next item
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // 3. Harmonic Load Balancing: If we have many open bins, penalize opening a new one
    // unless the fit is exceptionally good.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 25.0 + (open_bins_count as f64 * 2.0);
        }
        // Penalize opening a new bin if the item is small, as it's better to pack it into existing space.
        if item_size < 30 {
            score += 20.0;
        }
    }

    // 4. Fitting Constraint: If this is the last chance to fit the item in an existing bin,
    // lower the score to force acceptance and avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 5. Mean residual alignment: Avoid bins that deviate significantly from the mean
    // to keep bins balanced in their remaining capacity.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space avoidance: Penalize post_residual values that are too small to be useful
    // (typically < 10, as the minimum item size is 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open bins pressure: If we have many open bins, prioritize tighter packing
    // to consolidate and prevent leaving too many bins with high residuals.
    let bin_pressure = open_bins_count as f64 * 0.5;
    score += bin_pressure;

    // 3. Lookahead optimization: If the next item is large, favor bins that leave
    // at least enough room for that item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
