    // 4. Strategic new bin control:
    // If this is a new bin (bin_residual == bin_capacity), only choose it if
    // the existing bins are all forced into very poor fits (high mean_residual).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Make it harder to open a new bin if an existing bin could fit it
            score += 40.0 + (mean_residual * 0.5);
        }
    } else {
        // Encourage using existing bins that have a residual close to the current mean
        // to keep the spread of residuals low.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize configurations that leave small, unusable gaps.
    // If post_residual is small but > 0, it's often better to have 0 or > 20.
    if post_residual > 0 && post_residual < 15 {
        score += 40.0 * (1.0 - (post_residual as f64 / 15.0));
    }

    // 2. Lookahead Coupling: Reward bins that can accommodate the next_item_size.
    if next_item_size > 0 {
