    // 3. Mean Residual Balancing: Prevent fragmentation. 
    // Penalize bins that deviate significantly from the global average residual.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 4. New Bin Thresholding: 
    // When considering a new bin (bin_residual == bin_capacity), make it expensive 
    // unless the current fit is extremely poor (large post_residual penalty).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high to encourage compaction.
        score = 65.0 + (mean_residual * 0.5);
    }

    // 5. Progression Scaling: As the stream nears the end, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
