pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score. 
    // Best Fit Decreasing logic is the baseline, but we add penalties for "fragmentation" 
    // and rewards for "complementary pairing" using lookahead.

    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space" (small residuals that are hard to fill).
    // Residuals in the range [1, 10] are particularly toxic.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Harmonic coupling: Reward placements that create a residual capable of 
    // hosting the next item if the next item is large.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Excellent: The current bin can accommodate the next item.
            score -= 25.0;
        } else if post_residual > 0 {
            // Neutral/Poor: The next item will force a new bin unless another bin fits it.
            score += 5.0;
        }
    }

    // 3. Pressure for New Bin: If we are forced to open a new bin, we want to 
    // keep open_bins_count low. If this is a new bin (residual == capacity),
    // only pick it if no other bins are available or if existing ones are highly fragmented.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Highly penalize opening a new bin if an existing bin could fit it.
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            // Necessary evil.
            score -= 10.0;
        }
    }

    // 4. Global balance: Encourage filling bins that are already "half-empty" 
    // relative to the mean to reduce the number of active bins.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    let mean_fill = 1.0 - (mean_residual / bin_capacity as f64);
    if fill_ratio < mean_fill {
        score += 10.0 * (mean_fill - fill_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
