        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Open Bins Pressure: Discourage opening new bins (or using bins that increase open_bins_count)
    // unless the fit is extremely tight (Best Fit behavior).
    if bin_residual == bin_capacity {
