    // We penalize residuals in the range [1, 9] heavily as they are likely unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic lookahead: prioritize placements that leave a residual 
    // capable of fitting the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward perfect or near-perfect fit for the next item
            score -= (bin_capacity - post_residual) as f64 * 0.5;
        } else {
            // Penalize if this placement prevents the next item from fitting here
            score += 20.0;
        }
    }

    // 3. Density management: Balance the use of existing bins.
    // If few bins fit the item, we are constrained; if many fit, we should pick 
    // the one that leaves the smallest residual (Best Fit).
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64) * 2.0;
    }

    // 4. New bin thresholding:
    // Only open a new bin if the current residual is significantly inefficient
    // or if we are at the very beginning of the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // Penalize opening a new bin heavily unless we are early in the process
        // or the mean residual of existing bins is already very low.
        score += 60.0 + (progress * 40.0) + (mean_residual * 0.5);
    }

    // 5. Modulo-based capacity optimization:
    // Favor residuals that align with common factors of the capacity (e.g., 20, 25, 50).
    let rem = post_residual % 25;
    if rem == 0 {
        score -= 10.0;
    } else if rem > 20 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "Dead Space" (gaps smaller than the smallest possible item, 
    // approximated by the threshold of 10). If we create a gap < 10, it's likely wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Pressure to consolidate: Penalize opening new bins when space is available.
    // If this is a new bin (bin_residual == bin_capacity), add a heavy cost 
    // inversely proportional to the number of existing bins.
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64 * 2.0);
