        }
    }

    // 4. Density Balancing: If we are creating a new bin, penalize it unless necessary
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Only open a new bin if the current open bins are very full (mean_residual low)
            score += 30.0 + (mean_residual * 0.5);
        } else {
            // No choice, must open
            score -= 100.0;
        }
    }

    // 5. Progression Scaling: As we approach the end of the stream, prioritize packing tighter
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. Fragmentation avoidance: Penalize opening a new bin if we have many empty-ish bins
    if bin_residual == bin_capacity && open_bins_count > 5 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
