    let is_new_bin = bin_residual == bin_capacity;

    // Base score: We prefer smaller post-residuals (Best Fit).
    let mut score = post_residual as f64;

    // Penalty for opening new bins: Only open if forced or if current fit is extremely poor.
    if is_new_bin {
        // High base penalty for new bins, softened by the progression of the stream.
        score += 45.0 * (1.0 - progress * 0.5);
    } else {
        // Reward for bins that are becoming "tight" (filling up efficiently).
        // If post_residual is small (e.g., < 10), we reward it heavily to consolidate space.
        if post_residual < 10 {
            score -= 15.0;
        }

        // Lookahead heuristic: If the next item fits into the current post_residual,
        // we heavily favor this bin to keep the packing density high.
        if next_item_size > 0 && post_residual >= next_item_size {
