    // Fitting density awareness:
    // If this is the only bin that can fit the item, we shouldn't be too picky,
    // but if we are at the end of the stream, we prioritize closing bins.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 5.0;
    }

    // Final alignment: ensure that we don't return negative values that might break
    // logic expecting positive scores, though lower is always prioritized.
    score.max(0.0)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let cap = bin_capacity as f64;

    // Penalty for creating small, unusable gaps (1..10 range is highly fragmented)
    // We use a non-linear exponential penalty for post_residual values near 0-10
    let fragmentation_penalty = (10.0 - post).exp() * 0.5;

    // Favor bins that align well with the next item (lookahead synergy)
    // If next_item_size is 0, we treat it as neutral
    let lookahead_synergy = if next_item_size > 0 {
        let gap_diff = (post - next_item_size as f64).abs();
        gap_diff * 0.2
    } else {
        0.0
    };

    // Global state awareness: 
    // Reward keeping residual space close to the mean to maintain uniform bin filling
    let variance_penalty = (post - mean_residual).powi(2) * 0.1;

    // New bin logic:
    // If bin_residual == cap, we are evaluating opening a new bin.
    // We scale the cost of opening a new bin based on progress and current open bins.
    let mut score = if res == cap {
        // High penalty for opening a new bin early in the stream
        // Decreases as we approach the end to avoid leaving many half-empty bins
        (cap * 1.5) * (1.0 - progress * 0.5) + (open_bins_count as f64 * 2.0)
    } else {
        // Scoring for existing bins:
        // Prioritize smaller post_residual (Best Fit logic)
        // Add non-linear coupling with stream progress
        post + fragmentation_penalty + lookahead_synergy + variance_penalty
    };

    // Critical constraint: If this is the only bin that fits the item, 
    // force selection by lowering the score significantly
    if fitting_bins_count == 1 && res != cap {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
