        if fitting_bins_count == 1 && post_residual < 20 {
            score -= 8.0;
        }

        // 6. Mean Residual Balancing: Avoid bins that deviate significantly from average density.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit)
    // Add non-linear penalty for creating small "dead zones" (residuals 1-9)
    let dead_zone_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post) * 5.0
    } else {
        0.0
    };

    // Reward packing efficiency relative to the mean: 
    // If the bin is tighter than average, reward it, weighted by stream progress.
    let efficiency_bonus = (mean_residual - post) * progress;

    // Lookahead logic: 
    // If the next item fits into the current post_residual, prioritize keeping it open.
    let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual {
        -25.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Penalty for opening a new bin (where bin_residual == bin_capacity)
    // We scale the cost of opening a new bin by the current number of open bins 
    // to discourage fragmentation as the stream progresses.
    let new_bin_penalty = if bin_residual == bin_capacity {
        30.0 + (open_bins_count as f64 * 2.0 * (1.0 - progress))
    } else {
        0.0
    };

    // Interaction term: Penalize wasting space in the early stages of the stream
    // more heavily than in the late stages (where we just want to finish).
    let temporal_waste_penalty = (post.powf(1.5)) * (1.0 - progress);

    post + dead_zone_penalty + temporal_waste_penalty + new_bin_penalty + lookahead_bonus - efficiency_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

