    let mut score = post;

    // Penalty for "bad" small residuals that cannot accommodate typical items (10-30).
    // Creates a non-linear "cliff" where we prefer to keep bins empty rather than creating tiny unusable gaps.
    if post > 0.0 && post < 15.0 {
