    // 3. Modulo-based Fragment Avoidance:
    // Avoid leaving small, unusable gaps (e.g., < 10) unless it's a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Capacity Fraction Logic:
    // If we are in the later stages of the stream, prioritize aggressive filling (lower the score).
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    // 5. Fitting Constraint:
    // If this is the only bin that can fit the item, prioritize it strongly to avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Mean Residual Balancing:
    // Penalize bins that deviate significantly from the mean residual to keep bin levels uniform.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
