    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
        // Bonus for "tight fit" with next item
        score -= (post_residual - next_item_size) as f64 * 0.5;
    }

    // 4. Scarcity Penalty: If this is the only bin that fits the current item, 
    // force its selection to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. New Bin Thresholding: Penalize opening a new bin unless the current open bins are very full.
    // If bin_residual == bin_capacity, we are evaluating the cost of opening a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of existing bins is already small (< 20)
        // or if we are very early in the stream.
        if mean_residual > 20.0 && (step_index as f64 / total_items as f64) > 0.1 {
            score += 60.0;
        } else {
            score += 25.0;
        }
    }

    // 6. Balance usage: Prevent creating too many open bins if the mean residual is high
    if open_bins_count > 5 {
        score += (open_bins_count as f64 - 5.0) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small to fit common items (10-20 range).
    // If post_residual is between 1 and 9, it is highly likely to become unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If next_item_size is known, favor bins that leave room for it.
    if next_item_size > 0 {
