    // 3. Open Bins Pressure: Penalize opening new bins unless the fit is extremely tight (Best Fit).
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy tax unless no other bin fits.
    if bin_residual == bin_capacity {
