            score += 150.0; // Strong disincentive to open a new bin if space exists elsewhere
        } else {
            score -= 10.0; // Neutralize for unavoidable new bin
        }
    }

    // 4. Mean Residual Balancing: Avoid creating bins that deviate significantly from the mean.
    // This keeps the bins filled at a similar density.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // 5. Progression Weight: As we near the end of the stream, prioritize finishing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
