        score -= (capacity - bin_residual as f64) * 0.1;
    }

    // Prioritize bins that are "last chances" to avoid creating fragmented bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

