        }
    }

    // 5. Progress-Weighted Balancing:
    // As we approach the end of the stream (step_index / total_items), be more aggressive
    // about packing density to avoid trailing bins.
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 20.0) * (post_residual as f64 / bin_capacity as f64);

    // 6. Mean Residual Correction:
    // If this bin's residual is significantly lower than the mean of other bins,
    // it's a good candidate to "tighten up".
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
