        // Only open a new bin if the current mean residual is already very low (bin packing is tight)
        // or if we are at the very beginning of the stream.
        let progress = step_index as f64 / total_items as f64;
        score += 40.0 + (mean_residual * 0.5) + (progress * 20.0);
    }

    // 5. Penalize "useless" small gaps: Gaps between 1 and 9 are often unreachable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best Fit Decreasing (BFD) core: prioritize smaller post_residual
    // 2. Penalize opening new bins early in the stream unless necessary
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && progress < 0.95 {
            score += 45.0 + (mean_residual * 0.5);
        } else {
            score += 20.0;
        }
    }

    // 3. Lookahead logic: If next_item_size exists, penalize bins that cannot fit it
    // if we place the current item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // This bin becomes "useless" for the next item; penalize it.
            // Scale penalty by how much space is wasted (post_residual).
            score += (post_residual as f64) * 0.6;
        } else {
            // Reward bins that can accommodate both current and next items.
            score -= (next_item_size as f64) * 0.4;
        }
    }

    // 4. Tightness bias: If only one bin fits, prioritize it to conserve open bins
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // 5. Entropy reduction: penalize bins that deviate significantly from mean_residual
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the new bin candidate (where residual == capacity) based on progress
    // As we reach the end of the stream, opening a new bin is heavily penalized.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 200.0 + 50.0 
    } else {
        0.0
    };

    // Best Fit Decreasing logic: prioritize smaller post_residual
    // Non-linear coupling: square the post_residual to punish large gaps
    let mut score = post * post / 100.0;

    // Lookahead logic: If the next item exists, penalize bins that leave just enough space
    // to be "awkward" (e.g., 1-9 units remaining) if the next item is large.
    if next_item_size > 0 {
        if post < next_item_size as f64 && post > 0.0 {
            score += (next_item_size as f64 - post) * 2.0;
        }
    }

    // Encourage density: penalize bins that deviate significantly from the current mean_residual
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.5;

    // If only one bin fits the item, treat it as a "must-use" by lowering its score
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' that cannot accommodate common item sizes.
    // Small residuals (< 10) are extremely problematic as they become unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // Lookahead logic: If the next item is large, favor bins that leave enough room for it.
    // If the current post_residual is smaller than the next item, we penalize the bin.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        } else {
            // Reward bins that leave a 'perfect' fit for the next item (residual close to 0 after next item)
            let spare_after_next = post_residual - next_item_size;
            if spare_after_next < 5 {
                score -= 15.0;
            }
        }
    }

    // Harmonic constraint: Favor bins that align with high-density capacity fractions.
    // Bins with residuals divisible by 20 (1/5 capacity) are often more flexible.
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // Threshold management: If this is the only bin that fits the item (fitting_bins_count == 1),
    // we should generally prefer it, unless the residual is critically small.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 30.0;
    }

    // If bin_residual == bin_capacity, we are evaluating a NEW bin.
    // Penalize opening a new bin heavily unless the current open bins are all too full.
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64 * 2.0);
    }

    // Progression scaling: As we approach the end of the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "dead space": gaps smaller than the smallest likely item (10)
    // but larger than 0 are highly inefficient.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If the next item exists, penalize bins that 
    // leave a post_residual too small to accommodate the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Pressure management: If we are nearing the end of the stream, 
    // we should be more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * (1.0 + progress * 2.0);

    // 4. New bin penalty: If this is an empty bin, add a base cost 
    // to force the algorithm to prefer filling existing bins.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, weighted by how many bins are already open.
        score += 45.0 + (open_bins_count as f64 * 1.5);
    } else {
        // If it's an existing bin, reward it if it's the only one that fits.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // 5. Mean residual alignment: Avoid bins that deviate significantly from 
    // the mean residual of all open bins to keep bin levels uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // A bin is a new bin if bin_residual == bin_capacity.
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit logic: smaller residual is better).
    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin unless necessary.
    if is_new_bin {
        // Only open new if we have many bins already or if it's the absolute last resort.
        // We add a heavy penalty based on the number of currently open bins.
        score += 85.0 + (open_bins_count as f64 * 2.5);
    } else {
        // 2. Reward bins that create a perfect fit for the current item.
        if post_residual == 0 {
            score -= 40.0;
        }

        // 3. Aggressive 2-step lookahead: 
        // If the next item can fit in the post_residual, drastically reduce score.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 50.0;
