            score -= (100.0 - post_residual as f64) * 0.1;
        }

        // 4. Avoid creating "sliver" residuals that are too small for common items (e.g., < 10).
        if post_residual > 0 && post_residual < 10 {
            score += 30.0;
        }

        // 5. Balance against the mean_residual of open bins.
        // If this bin's post_residual is significantly worse than the average, penalize it.
        if post_residual as f64 > mean_residual {
            score += (post_residual as f64 - mean_residual) * 0.5;
        }
    }

    // 6. If this is the only bin that can fit the item, prioritize it strongly.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
