        if open_bins_count > 0 {
            score += 45.0;
        }
        // If this is a new bin, we want to favor it only if the current mean_residual 
        // suggests existing bins are already too crowded to accommodate future items.
        if mean_residual < 20.0 {
            score += 20.0;
        }
    }

    // 5. Fitting constraints: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Modulo-based "Bin Packing Class" alignment:
    // Try to align bin residuals to multiples of 25 to leave room for standard item sizes.
    let remainder = post_residual % 25;
    if remainder == 0 {
        score -= 10.0;
    } else if remainder > 20 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small "orphaned" gaps (1..10)
    // where no future items are likely to fit. Reward bins that keep the mean_residual
    // balanced with the next_item_size requirement.

    let mut score = post_residual as f64;

    // Penalty for creating "dead space": gaps smaller than 10 are usually wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // Penalty for opening a new bin prematurely: 
    // If this is a new bin (bin_residual == bin_capacity), penalize based on open_bins_count
    // and how many other bins could have taken this item.
    if bin_residual == bin_capacity {
