    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0; // Penalize if this placement prevents the next item from fitting
        }
    }

    // Pressure to consolidate: Penalize high open_bins_count to encourage dense packing
    score += (open_bins_count as f64) * 0.5;

    // Reward "Perfect Fit" (Best Fit Decreasing style)
    if post_residual == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space" (too small to fit typical items, yet too large to be optimal)
    // We penalize post_residual if it's smaller than the next item but larger than 0.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // 2. Reward for "Perfect Fit" or "Tight Fit"
    // If post_residual is 0, it's a perfect fill.
    if post_residual == 0 {
