    }

    // 3. Lookahead optimization: If the next item fits perfectly in the new post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let remaining_after_next = post_residual - next_item_size;
        // Reward configurations where the next item leaves a very small residual (near-perfect 2-step pack)
        if remaining_after_next == 0 {
