    // 4. Heuristic for new bin placement
    // If the bin is new (bin_residual == bin_capacity), penalize it based on how many bins are already open
    // to discourage opening new bins unless the fit in existing bins is truly poor.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64 * 0.5);
    }

    // 5. Global state normalization
    // Penalize bins that deviate significantly from the mean_residual to keep residuals uniform
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 6. Urgency factor
    // As we approach the end of the stream, prioritize closing bins over opening new ones
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
