    // reduce the penalty for a poor fit to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // 5. Mean Residual Balancing: If this bin's residual is significantly better than the global mean,
    // reward the choice to keep the bin state "tight".
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize creating tiny slivers that are likely to be wasted (1-9 range)
    let fragmentation_penalty = if post < 10.0 && post > 0.0 {
        (10.0 - post) * 5.0
    } else {
        0.0
    };

    // Reward bins that become "tight" (post_residual near 0)
    let tightness_reward = -1.0 * (100.0 - post).powf(1.5) * 0.1;

    // Lookahead logic: if the next item is large, prioritize keeping space open.
    // If next_item_size is 0 (end of stream), prioritize closing bins (lower post_residual).
    let lookahead_factor = if next_item_size > 0 {
        let fit_next = if post >= next_item_size as f64 { -20.0 } else { 10.0 };
        fit_next * (1.0 - progress)
    } else {
        post * 0.5
    };

    // Penalty for opening a new bin when existing bins are available
    let new_bin_penalty = if bin_residual == bin_capacity && open_bins_count > 0 {
        (50.0 * (1.0 + progress)) + (mean_residual * 0.5)
    } else {
        0.0
    };

    // Bias towards utilizing bins that are already partially filled (lower mean_residual)
    let utilization_bias = if bin_residual < bin_capacity {
        (bin_capacity as f64 - bin_residual as f64) * 0.2
    } else {
        0.0
    };

    let mut score = post + fragmentation_penalty + tightness_reward + lookahead_factor + new_bin_penalty - utilization_bias;

    // Boost score if this is the last fitting bin to prevent unnecessary new bin creation
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

