    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Global Efficiency: If the current residual is larger than the mean residual of all open bins, 
    // it is a "loose" bin; penalize placing here to encourage tighter packing in tighter bins.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    }

    // 6. Progress Scaling: As we near the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
