    } else {
        0.0
    };

    // Global strategy: Towards the end of the stream, prioritize aggressive packing (Best Fit)
    // to consolidate items, whereas early on, prioritize keeping bins flexible.
    let consolidation_pressure = (1.0 - progress) * (open_bins_count as f64 * 2.0);

    // If this is a new bin, apply a significant base cost that decays as the stream progresses
    // and as we run out of efficient space in existing bins.
    let new_bin_cost = if bin_residual == bin_capacity {
        50.0 - (progress * 20.0) + (mean_residual * 0.5)
    } else {
        0.0
    };

    // If only one bin can fit the item, we are forced to use it; lower the score to prioritize it.
    let scarcity_bonus = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -25.0
    } else {
        0.0
    };

    let mut score = post + dead_zone_penalty + lookahead_factor + consolidation_pressure + new_bin_cost + scarcity_bonus;

