            // We must open a new bin; normalize the cost.
            score = 50.0;
        }
    } else {
        // Encourage filling bins that are already closer to the mean residual to keep bins uniform.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // Dynamic time horizon: As we approach the end of the stream, prioritize tight fits more aggressively.
    score += progress * 15.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize Best Fit (minimize post_residual)
    let mut score = post;

    // Penalty for creating a 'bad' residual (Dead Space):
    // Residuals between 1 and 9 are extremely difficult to fill.
    // We penalize these heavily, scaling the penalty by progress to be more 
    // conservative as we approach the end of the stream.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 15.0 * (1.0 + progress);
    }

    // Lookahead coupling: If a second item is known, favor bins that can 
    // accommodate the next item (post_residual >= next_item_size).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 * (1.0 - progress);
        } else {
            score += 15.0 * progress;
        }
    }

    // Dynamic density management:
    // If we have many open bins, penalize opening a new one (bin_residual == bin_capacity).
    // If this is the only bin that fits, prioritize it heavily to avoid fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 10.0;
    } else if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Variance penalty:
    // Penalize bins that deviate significantly from the mean_residual of open bins
    // to encourage packing bins to similar levels of fullness.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, penalize based on the current mean residual.
    // We want to avoid opening a new bin if the current bins are already quite empty.
    if bin_residual == bin_capacity {
        score += mean_residual * 1.5;
        // If we have very few items left, opening a new bin is expensive.
        score += (total_items - step_index) as f64 * 0.05;
    } else {
        // 2. Best-Fit logic: penalize larger post_residuals to keep bins tight.
        // Harmonic-like approach: prioritize filling bins to specific thresholds (e.g., 10, 20, 25).
        let penalty = (post_residual % 10) as f64 * 2.0;
        score += penalty;

        // 3. Lookahead logic: if the next item fits into the current post_residual, 
        // we heavily prioritize this bin (negative score).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= (next_item_size as f64 * 1.8);
        }
    }

    // 4. Scarcity adjustment: if this is the only bin that fits the current item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Normalization: adjust by bin density to prevent fragmentation.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score += fill_ratio * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual values that create unusable gaps (1..9).
    // Small gaps are death for future packing efficiency.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64).sqrt();
    }

    // 2. Best-Fit Bias: Encourage filling bins as tightly as possible.
    // We favor lower post_residual, but we modulate this by the number of bins.
    score += (post_residual as f64) * 0.1;

    // 3. New Bin Thresholding: If we are considering a new bin, penalize it based on open_bins_count.
    // If the bin is new, bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
        // If we have many open bins, we really don't want to open another unless necessary.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Lookahead Integration: If the next item is large, avoid small post_residuals 
    // that effectively "waste" the bin for that upcoming item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // 5. Global Pressure: As we approach the end of the stream, prioritize closing bins
    // over maintaining many open ones.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // 2. Lookahead Synergy: If post_residual is close to next_item_size, reward this bin heavily.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward placements that leave exactly enough space for the next item
        score -= 50.0 * (1.0 / (1.0 + diff));
    }

    // 3. Mean Residual Balancing: Avoid bins that deviate significantly from the global average
    // to keep bin utilization uniform.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += 0.5 * dev_from_mean;

    // 4. New Bin Thresholding:
    // If this is an empty bin (bin_residual == bin_capacity), it is the fallback.
    // We penalize opening a new bin heavily unless the fitting_bins_count is low or 
    // the current item is very large (making it hard to fit into existing residuals).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 10.0; // Must open
        } else {
            // Apply a stiff penalty to opening a new bin if we have fits available
            score += 45.0 + (item_size as f64 * 0.5);
        }
    } else {
        // 5. Criticality: If this is the only bin that fits the item, prioritize it.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // 6. Progress Weighting: As we reach the end of the stream, prioritize tighter packing
    // to reduce the total number of bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual: 0 is perfect (Best Fit).
    // Penalize large post_residual (wasted space).
    let mut score = post_residual as f64;

    // Lookahead logic: If the next item can fit in the current post_residual, 
    // prioritize this bin to preserve future capacity.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // Dynamic constraint: If this is the only bin that can fit the item, 
    // force it to be highly attractive to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Global state awareness: If we have many open bins, penalize opening a new one.
    // If bin_residual == bin_capacity, we are evaluating the cost of opening a new bin.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Calculate a "density penalty" for opening a new bin.
            // As we approach the end of the stream, be more conservative with new bins.
            let progress = step_index as f64 / total_items as f64;
            score += 20.0 + (open_bins_count as f64 * 2.0) + (progress * 15.0);
        }
    } else {
        // Favor bins that have a residual closest to the mean_residual of all bins
        // to keep bin utilization balanced.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // Secondary penalty: Avoid leaving small "slivers" (e.g., 1-5 space) which are hard to fill.
    if post_residual > 0 && post_residual < 6 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base cost is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating a "sliver" (fragmentation)
    // Slivers are small residuals that are unlikely to fit future items.
    // We penalize post_residual values between 1 and 9 heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Non-linear coupling: As the stream progresses, prioritize filling bins 
    // more tightly to avoid opening new ones late in the process.
    if !is_new_bin {
        score -= (1.0 - progress) * (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Lookahead logic: If we know the next item, penalize current placements 
    // that would make the next item harder to place in this bin.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0; 
        } else {
            // Reward placements that leave room for the next item
            score -= 15.0;
        }
    }

    // If this is the only bin that can fit the item, we are forced to use it.
    // We lower the score to ensure it is prioritized over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 100.0;
    }

    // New bin penalty: Heavily penalize opening a new bin unless existing 
    // options are extremely poor (i.e., would result in high fragmentation).
    if is_new_bin {
        score += 40.0 + (progress * 20.0);

        // If many bins are already open, opening another is costly.
        score += (open_bins_count as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (waste)
    // 2. Harmonic Gap Balancing: Favor residuals that align with common item sizes (33, 50, 25)
    //    We reward residuals that are multiples of 25 to keep bins "flexible" for future items.
    let harmonic_penalty = (post_residual % 25) as f64 * 1.5;
    score += harmonic_penalty;

    // 3. Lookahead Synergy: If the next item fits into the current post_residual, drastically reduce score.
    if next_item_size > 0 && post_residual >= next_item_size {
