        score = new_bin_base + openness_factor;
    } else {
        // Penalize bins that are becoming too full to accommodate average future items
        if post_residual < 20 {
            score += 15.0;
        }
    }

    // 6. Progression adjustment: As the stream nears the end, prioritize packing tightly
    //    to close out open bins (minimize empty space).
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
