        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Prioritize filling the tightest bin (Best Fit). 
    // We favor bins where the post_residual is minimized, but only if it's not a "dead" gap.
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    // 3. Pressure against opening new bins:
    // If the bin is brand new (bin_residual == bin_capacity), apply a heavy penalty
    // that scales with how many bins are already open (to discourage fragmentation).
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 2.5);
    }

    // 4. Lookahead logic: If the next item can fit in the current post_residual,
    // reward this placement to prevent creating a new bin later.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // 5. If this is the last chance for the current item (fitting_bins_count == 1),
    // reduce the penalty for a new bin slightly, but strictly prefer filling an existing one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 6. Normalize against the mean residual to keep bins balanced.
    // If the current bin's post_residual is significantly worse than the average, penalize it.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "fragmented" space (too small for most items)
    // If post_residual is small but not zero, it's often a "dead" zone.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead optimization: If the next item fits perfectly in the post_residual,
    // we should prioritize this bin (Best-Fit-Lookahead).
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5;
    }

    // 3. New Bin Thresholding:
    // If we are considering a new bin (bin_residual == bin_capacity), 
    // only pick it if the mean_residual of existing bins is already quite small,
    // suggesting we are "tightly packed" and shouldn't force an item into a bad fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other bins can accommodate it.
            score += 60.0 + (mean_residual * 0.5);
        } else {
            // If no other bin fits, this is our only choice.
            score = 0.0;
        }
    } else {
        // 4. Prefer bins that keep the overall mean residual high (keeping flexibility).
        // If placing this item makes the bin's residual significantly lower than the mean,
        // it might be a suboptimal choice.
        if (post_residual as f64) < (mean_residual * 0.8) {
            score += 5.0;
        }
    }

    // 5. Progression awareness: As we approach the end of the stream, 
    // prioritize closing existing bins (packing them tighter).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
