            score += 15.0;
        }
    }

    // 3. Global Efficiency: If current bin residual is far from the mean, 
    // we want to pull it closer to the mean to maintain balance.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += 0.2 * residual_diff;

    // 4. New Bin Thresholding: Discourage opening new bins early in the stream.
    // If this is a new bin (bin_residual == bin_capacity), make it expensive 
    // unless the current open bins are all very tight (low mean_residual).
    if bin_residual == bin_capacity {
        score += 35.0 - (progress * 10.0);
        if open_bins_count > 0 && mean_residual > 20.0 {
            score -= 15.0; // Allow opening if existing bins are inefficient
        }
    }

    // 5. Finality: At the end of the stream, prioritize space consolidation.
    if progress > 0.95 {
        score -= post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
