pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Best-Fit Decreasing / Harmonic-Adaptive hybrid
    // The objective is to minimize post_residual (Best Fit) while reserving space for next_item_size

    let mut score = post_residual as f64;

    // 1. Penalty for creating "Dead Space" (space < 10, as 10 is the minimum item size)
    // If post_residual is small but > 0, it is often a "sliver" that can't be filled.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 2. Harmonic Lookahead: If next_item_size can fit in the post_residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further reward if it creates a perfect fit for the lookahead
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // 3. Pressure management: If we are nearing the end of the stream, prioritize closing bins
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // If this bin is the last chance for this item, prioritize it
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // 4. New bin thresholding:
    // If bin_residual == bin_capacity, this is a new bin. 
    // We only want to open a new bin if the existing bins are poor fits (post_residual > 20).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // High penalty for opening new bin if existing bins have decent space
            score = 60.0 + (mean_residual * 0.5);
        }
    }

    // 5. Modulo-based "Bin Packing" affinity: 
    // Penalize bins that leave remainders that are not multiples of common item sizes (e.g., 20, 25, 50)
    let remainder_penalty = (post_residual % 10) as f64;
    score += remainder_penalty * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "dead space": gaps smaller than 10 are usually useless for future items
    // If the post_residual is in the range [1, 9], it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Prioritize Best-Fit behavior: favor bins that result in smaller residuals
    // This is the baseline, but we adjust by the number of bins available to avoid fragmentation.
    score += (open_bins_count as f64) * 0.5;

    // 3. Lookahead logic: if we have a next item, try to leave enough room for it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect: we can fit the next item too, reward this bin
            score -= 20.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Bad: we create a gap that is too small for the next item
            score += 15.0;
        }
    }

    // 4. Pressure: If this is the only fitting bin, we are forced to use it.
    // Lower the score to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. New bin penalty: Only open a new bin if the "best" existing bin is truly terrible
    // (e.g., leaving a very small, unusable gap).
    if bin_residual == bin_capacity {
        // Higher base cost for opening a new bin
        score += 25.0;
        // Reduce the penalty if the stream is early (to allow better packing later)
        score -= (step_index as f64 / total_items as f64) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals to favor tight packing.
    // This naturally pushes the score lower for bins that become nearly full.

    // 2. Lookahead Penalty: If the post_residual is too small to fit the next item,
    // penalize it, unless the post_residual is very close to 0 (perfect fit).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 5 {
        score += 20.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // 3. Perfect Fit Bonus: Heavily reward creating a perfectly full bin.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 4. Mean Residual Balancing: If the bin's residual is significantly worse than the 
    // global mean, penalize it to avoid scattering items across many bins.
    if bin_residual as f64 > mean_residual * 1.2 {
        score += 15.0;
    }

    // 5. New Bin Thresholding: If we are opening a new bin (bin_residual == bin_capacity),
    // only choose it if the fitting_bins_count is low, suggesting we are struggling to 
    // pack into existing bins.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if other options exist
            score += 45.0 + (fitting_bins_count as f64 * 2.0);
        } else {
            // If no other options, prioritize the new bin
            score -= 10.0;
        }
    }

    // 6. Progressive Tightening: As the stream nears completion, become more aggressive
    // about packing into existing bins to avoid stranded items.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
