    }

    // If this is the only bin that fits, prioritize it heavily to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Dynamic behavior: As we approach the end of the stream, prioritize closing bins
    // to keep the total bin count low.
    if progress > 0.8 {
        score -= (100.0 - post_residual as f64) * 0.1;
    }

    // Penalty for opening a new bin. 
    // We only open a new bin if the existing options are very poor (high post_residual).
    if is_new_bin {
