        score = 50.0;

        // If we have many open bins with large residuals, opening a new one is discouraged.
        if mean_residual > 30.0 {
            score += 40.0;
        }

        // As the stream finishes, penalize opening new bins more aggressively.
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit principle)
    // We penalize larger post_residuals to keep the bin tight.
    let mut score = post;

    // Non-linear penalty for creating "dead space" (very small residuals that are unlikely to fit future items)
    // If post_residual is < 10, it's likely unusable for the range 10..80.
    if post > 0.0 && post < 10.0 {
        score += 15.0 * (10.0 - post);
    }

    // Dynamic Lookahead Coupling:
    // If we have a next item, we want a post_residual that can accommodate it.
    // We reward bins that leave enough space to fit the next item if it's large.
    if next_item_size > 0 {
        if post >= next_item_size as f64 {
            score -= 5.0; // Reward perfect fit for the next item
        } else if post > 0.0 {
            score += 20.0; // Penalize if we can't fit the next item in this bin
        }
    }

    // Progress-based pressure:
    // As the stream progresses, we become more conservative about opening new bins.
    // If fitting_bins_count is 1, we are at a critical decision point.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // Penalize opening a new bin (where bin_residual == bin_capacity)
    // The penalty grows as we progress to avoid fragmentation early.
    if bin_residual == bin_capacity {
        score += 45.0 + (30.0 * progress);
    }

    // Global efficiency coupling:
    // If the mean_residual of current bins is high, we are already fragmented.
    // Penalize placing in bins that deviate significantly from the mean to encourage consolidation.
    let deviation = (post - mean_residual).abs();
    score += 0.5 * deviation;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
