    }

    // 3. Fragmentation Avoidance: If this is the last fitting bin, prioritize it to keep other bins open
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // 4. Global Load Balancing: Avoid opening new bins if the current average residual is high
    // If we are considering a new bin (residual == capacity), penalize it based on mean_residual
    if bin_residual == bin_capacity {
        score += mean_residual * 0.5;
        // Penalize opening new bins if we have many bins already
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. Harmonic Class Logic: Prefer filling bins to specific thresholds (e.g., 50, 75, 90)
    // to keep the bin occupancy high for incoming items of unknown distribution.
    if post_residual == 0 {
        score -= 25.0; // Perfect fit bonus
    } else if post_residual > 20 && post_residual < 30 {
        score += 10.0; // Avoid leaving moderate gaps
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
