    // it's often worse than leaving a larger gap.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead logic: if we know the next item, penalize bins that cannot fit it
    // if we only have one or two bins open.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        } else {
            // Reward bins that can accommodate both current and next items
            score -= 10.0;
        }
    }

    // Global state awareness: If we have many bins open, be more aggressive at filling 
    // existing bins (Best-Fit). If we have very few bins open, be more conservative.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    if open_bins_count > 5 {
        score -= fill_ratio * 5.0;
    }

    // Discourage opening a new bin unless the fit is extremely poor
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high to encourage packing
        score = 45.0;

        // If the item size is very large, opening a new bin is less penalized
        if item_size > 70 {
            score -= 20.0;
        }

        // If we are near the end of the stream, penalize opening new bins heavily
        let progress = step_index as f64 / total_items as f64;
        score += progress * 30.0;
    }

    // If this is the only bin that can fit the item, prioritize it to prevent
    // forcing a new bin creation unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_res;

    // Penalty for creating small, unusable gaps (1..10)
    // We apply a non-linear penalty to very small residuals that are hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_res + 1.0);
    }

    // Lookahead logic: If the next item is large, favor bins that leave enough space for it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
        }
