    }

    // New bin logic:
    // If this is an empty bin (bin_residual == bin_capacity), 
    // only pick it if it's strictly necessary (high penalty if fitting_bins_count > 0)
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
