            score += 45.0 + (30.0 * progress);
        }
    }

    // Coupling: Reward filling bins to a level close to the global mean_residual
    // This helps maintain a uniform density across all open bins.
    let dev = (post_res - mean_residual).abs();
    score += 0.5 * dev * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large remaining space (post_residual).
    // Using an exponential curve to heavily punish leaving large gaps.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic: Reward placements that leave a residual 
    // that is a multiple of common item sizes or small divisors of capacity.
    // This creates "bins" for future items.
    let harmonic_penalty = if post_residual > 0 {
        ((post_residual % 10) as f64) * 2.5
    } else {
        -50.0 // Huge reward for perfect packing (zero residual)
    };
    score += harmonic_penalty;

    // 3. Lookahead Sensitivity: If the next item fits into the current post_residual,
    // prioritize this bin to prevent fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
