        // Only open a new bin if the current mean_residual is very high (we have space elsewhere)
        // or if we have no fitting bins.
        if fitting_bins_count > 0 {
            score += 120.0 + (mean_residual * 2.0);
        } else {
            score -= 10.0; // Accept new bin if no other options exist
        }
    }

    // 5. Progression Scaling: As we reach the end of the stream, prioritize 
    // filling existing bins to minimize the final bin count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
