        }
    }

    // 4. Global balance: If the post_residual is below the mean_residual, 
    // it's an "efficient" bin compared to current state.
    if (post_residual as f64) < mean_residual {
        score -= 15.0;
    }

    // 5. Extreme tightness bonus:
    // If the item perfectly fills the bin, prioritize it above all else.
    if post_residual == 0 {
