    // 1. Dead Space Penalty: Penalize post_residual values that are likely to become 
    // unusable (e.g., between 1 and 9).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64).sqrt();
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, 
    // reward this placement significantly to prioritize packing pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Bin Pressure: If open_bins_count is high, penalize opening new bins 
    // (bin_residual == bin_capacity) to force consolidation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;

        // If it's a new bin, penalize it if there are other bins that could fit it
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Tightness bias: Favor bins that are already "tight" (low mean_residual) 
    // to keep the spread of residuals uniform.
    if mean_residual < post_residual as f64 {
        score += 10.0;
    }

    // 5. Progression weighting: As we near the end of the stream, 
    // aggressively minimize new bin openings.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // Base score is the residual space left after placement (Best Fit strategy).
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (residuals too small to fit common items).
    // If post_residual is between 1 and 9, it is likely unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Aggressive 2-step lookahead: 
    // If next_item_size can fit into the new post_residual, heavily reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further reward if it fills the bin near capacity (e.g., 90-100 range).
        if post_residual < 10 {
            score -= 20.0;
        }
    }

    // 3. Global state balancing:
    // If we have many open bins, penalize opening a new one (high bin_residual).
    // If the bin is brand new (bin_residual == bin_capacity), apply a heavy penalty
    // unless it's the only option or the current open bins are very full.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If average residual is already high, don't open new bins unnecessarily.
        score += mean_residual * 0.5;
    } else {
        // If this bin is already open, reward it based on how close it is to the mean.
        // This encourages "leveling" the residuals of open bins.
        score -= (mean_residual - post_residual as f64).abs() * 0.1;
    }

    // 4. Scarcity adjustment:
    // If this is the last bin that can fit the current item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 5. Progression scaling:
    // As we approach the end of the stream, prioritize packing tighter.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // We favor bins where post_residual is small (tight fit)
    score += post_residual as f64 * 1.2;

    // 2. Lookahead Synergy: If the next item fits into the post_residual, reward this placement.
    // This is a greedy lookahead to prevent stranding items.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Adaptive Thresholding: If we are near the end of the stream, 
    // become more aggressive about filling bins (Best-Fit).
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // 4. Global State Awareness: If we have many open bins, penalize opening new ones.
    // Only open a new bin if the fit is exceptionally good (near perfect) or forced.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if existing ones can fit the item
            score += 45.0 + (open_bins_count as f64 * 2.0);
        } else {
            // Base cost for opening a new bin when forced
            score += 10.0;
        }
    }

    // 5. Fragmentation Penalty: Penalize bins that deviate significantly from the mean residual.
    // This encourages "leveling" the bins to keep them equally available for future items.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.3;

    // 6. Extreme Fit Bonus: Reward near-perfect fills (post_residual near 0)
    if post_residual < 5 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
