    let mut score = post_residual as f64;

    // Penalty for creating "dead space": 
    // If post_residual is small but > 0, it's often better to fill it. 
    // We penalize small residuals that are too large to be useful for common items (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: If the next item could fit into this post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
