    }

    // Dynamic thresholding based on stream progression:
    // As the stream nears the end, we become more aggressive about filling existing bins
    // to avoid opening new ones.
    if !is_new_bin {
        // Encourage using existing bins that are close to the mean residual
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += 0.5 * deviation;
    } else {
        // Heavily penalize opening new bins unless the fitting_bins_count is zero
        // or we are very early in the stream.
        let new_bin_penalty = 40.0 + (progress * 60.0) + (open_bins_count as f64 * 2.0);
        score += new_bin_penalty;
    }

    // If this is the last chance for this item, reduce penalty for opening new bins
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    score
}

