    // Base score is the post-placement residual (Best-Fit principle: minimize remaining space)
    let mut score = post_residual as f64;

    // Penalty for creating a "fragmented" bin (residual too small for most items, but > 0)
    // We penalize values below 10 (the minimum item size) as they become unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if we know the next item, try to preserve space for it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item (Perfect fit bonus)
            if post_residual == next_item_size {
                score -= 15.0;
            } else {
                score -= 5.0;
            }
        } else {
            // Penalize bins that block the next item if they are the only option
            if fitting_bins_count == 1 {
                score += 10.0;
            }
        }
    }

    // Global state optimization: 
    // If we have many open bins, prioritize closing them (Best-Fit).
    // If we are late in the stream, be more aggressive about filling existing bins.
    let density_factor = (open_bins_count as f64) / (1.0 + mean_residual);
    score += density_factor * progress;

    // Handling the "New Bin" candidate (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins are "too full" to be efficient 
        // or if we have very few open bins (avoiding fragmentation).
        if open_bins_count == 0 {
            score = -100.0; // Force opening first bin
        } else {
            // Apply a high cost to opening new bins to encourage filling existing ones.
            // This cost scales with progress to allow for cleanup at the end of the stream.
            score += 40.0 * (1.0 - progress);

            // If we have many bins already, make opening a new one very expensive
            score += (open_bins_count as f64) * 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
