    // Base score is the post_residual (Best Fit logic).
    // We want to minimize post_residual to pack tightly.
    let mut score = post_residual as f64;

    // 1. Penalty for opening new bins: scale by progress to be more conservative late-game.
    if is_new_bin {
        score += (bin_capacity as f64) * (1.5 - progress);

        // If we have other bins that could fit this, penalize opening a new one heavily.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 2. Lookahead adjustment: If the next item is large, avoid leaving small residuals.
    // If post_residual is small (e.g., < 10), it's "dead space".
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
        // Reward bins that can accommodate the next item perfectly.
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.5;
        }
    }

    // 3. Global state balancing: Avoid cluttering many bins if we can pack into existing ones.
    // Penalize increasing open_bins_count if mean_residual is already high.
    if is_new_bin {
        score += mean_residual * 0.5;
    }

    // 4. Critical thresholding: If this is the last chance for an item, prioritize it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
