    // We want to pack tightly.
    score += post_residual as f64 * 1.5;

    // 2. Lookahead Synergy: If post_residual perfectly matches next_item_size, heavily reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual > next_item_size {
            // Reward bins that can accommodate the next item as a "safety" buffer.
            score -= (next_item_size as f64) * 0.8;
        } else {
            // Penalize bins that become too small to fit the next item.
            score += 40.0;
        }
    }

    // 3. Fragmentation Control: Avoid creating "dead" space smaller than the smallest likely item.
    // If post_residual is small but > 0, it's often a waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // 4. Mean Residual Balancing: Avoid bins that deviate significantly from the mean.
    // This helps keep bins balanced in terms of remaining capacity.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // 5. New Bin Thresholding:
    // If this is a new bin, make it expensive unless we really need it.
    if bin_residual == bin_capacity {
        // Increase cost of new bin as open_bins_count increases to discourage fragmentation.
        score += 70.0 + (open_bins_count as f64 * 2.0);

        // If we are near the end of the stream, be more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 50.0;
    }

    // 6. Last Chance Logic:
    // If this is the only bin that can fit, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post_residual (Best Fit principle).
    // We want to minimize post_residual, so lower values are naturally preferred.
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residuals that are unlikely to fit future items).
    // If post_residual is < 10, it's likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - progress);
    }

    // 2. Lookahead mechanism: If the next item fits into the current post_residual, 
    // prioritize this bin heavily to keep the bin tight.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Global state awareness: If we have many open bins, prioritize filling them
    // to keep the count low, unless the fit is extremely poor.
    if open_bins_count > 0 {
        score += (open_bins_count as f64) * 0.5;
    }

    // 4. Dynamic thresholding for new bins:
    // If this is a new bin (residual == capacity), we only want to pick it if 
    // the current fitting options are all "poor" (resulting in small, unusable residuals).
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin early on.
        score += 30.0 + (progress * 20.0);

        // If there are no other bins that can fit this item, the penalty is negated.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // 5. Balance against the mean residual: 
    // If this bin's residual after placement is better than the global mean, reward it.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: punish large post_residuals (Best-Fit principle)
    let mut score = post_res;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it prevents larger items from fitting. We penalize values that are 
    // hard to fill (e.g., 1-9 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: if next_item_size is large, prefer bins that leave 
    // enough space to accommodate it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        } else {
            score -= 5.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Dynamic thresholding: as we reach the end of the stream, prioritize 
    // packing tightly over keeping bins open.
    let tightness_factor = (mean_residual / bin_capacity as f64) * progress;
    score += tightness_factor * 20.0;

    // Penalty for opening new bins: only do so if the current fitting options 
    // are truly poor (Best Fit is usually preferred).
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // We only return a low score if the average residual is already high 
        // or if we are forced to (fitting_bins_count == 0).
        if fitting_bins_count > 0 {
            score += 40.0 + (open_bins_count as f64 * 2.0);
        } else {
            score -= 10.0;
        }
    } else {
        // For existing bins, reward bins closer to the mean residual to keep distribution uniform
        let deviation = (post_res - mean_residual).abs();
        score -= 0.1 * deviation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
