        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 6. Mean Residual Balancing: If this bin is significantly emptier than the average,
    // penalize using it to encourage "packing" into bins that are already similar to the mean.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
