    // If the new bin is the only option, fitting_bins_count will be 0.
    if res == bin_capacity as f64 {
        if fitting_bins_count > 0 {
            // Strong discouragement for opening new bins when space exists.
            score += 60.0 + (progress * 40.0);
        }
    } else {
        // Encourage using existing bins that are closer to the mean density.
        // This helps maintain a uniform fill rate across active bins.
        let density_diff = (res - mean_residual).abs();
        score += density_diff * 0.2;
    }

    // Final scaling: favor bins that are nearly full towards the end of the stream
    // to minimize the number of bins left open.
    score -= (1.0 - progress) * (bin_capacity as f64 - post) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Best-Fit Penalty: Minimize post_residual
    // We favor bins that result in small remainders.

    // 2. Harmonic/Modulo Logic:
    // Penalize remainders that are "useless" (too small to fit typical future items).
    // If post_residual is small but not zero, it creates "fragmentation".
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; 
