    // 4. Threshold Logic:
    // Avoid opening new bins unless necessary.
    if bin_residual == bin_capacity {
        // This is a new bin. Heavily penalize unless we have no other choice.
        if fitting_bins_count > 0 {
            score += 60.0;
        } else {
            score += 5.0; // Baseline cost of opening a new bin
        }
    }

    // 5. Progression Weighting:
    // As we approach the end of the stream, prioritize packing density over lookahead.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (post_residual as f64) * 0.5;
    }

    // 6. Mean Residual Balancing:
    // Discourage creating bins that deviate significantly from the current average residual.
    // This keeps the "quality" of open bins uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual to fill bins tightly (Best Fit),
    // but penalize small gaps that are likely to be wasted (dead space avoidance).
    // Also, apply pressure to keep open_bins_count low to minimize fragmentation.

    let mut score = post_residual as f64;

    // 1. Dead space penalty: If post_residual is small but > 0, it creates an unusable gap.
    // If next_item_size is available, penalize gaps that cannot fit the next item.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
