    // If it is a new bin (bin_residual == bin_capacity), add a significant penalty
    // unless no other bins can fit the item (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            // Must open a new bin, neutralize the penalty.
            score -= 10.0;
        }
    }

    // 3. Efficiency boost: If this bin fits the item perfectly, prioritize it heavily.
    if post_residual == 0 {
        score -= 20.0;
    }

    // 4. Global progress adjustment: As the stream nears completion, become more aggressive
    // about filling existing bins to avoid leaving stragglers.
    let progress = step_index as f64 / total_items as f64;
    score -= (progress * 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

