    }

    // 5. Mean Residual Balancing: If the current post_residual is significantly 
    // higher than the mean_residual of other bins, penalize it to keep bins uniform.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.8;
    }

