    if bin_residual == bin_capacity {
        // The cost of opening a new bin increases as we near the end of the stream
        // to prevent fragmentation.
        score += 30.0 + (progress * 50.0);
    }

    // Entropy balance: If we have many open bins, penalize spreading items thin.
    // Favor bins that are already partially filled (lower mean_residual).
    score += (open_bins_count as f64) * 2.0;
    score += (mean_residual - post) * 0.5;

    // Criticality check: If this is the only bin that fits, we are forced to take it.
    // Reduce score to ensure we don't prefer opening a new bin over a tight fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
