    // If this is the only bin that can fit the item, prioritize it strongly
    // unless it results in a very poor residual.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Progression scaling
    // As we approach the end of the stream, prioritize clearing existing bins (lower residuals).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

