    // it's a tight fit - reward it to consolidate space.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 5. New Bin Logic:
    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily 
    // unless we have no other choice (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
