    // 3. Lookahead logic: If post_residual can fit the next item, reward this bin
    let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size {
        -15.0 - (post_residual - next_item_size) as f64 * 0.1
    } else {
        0.0
    };

    // 4. Thresholding: Penalize opening a new bin unless the current mean_residual is too tight
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        if open_bins_count == 0 {
            -50.0 // Must open first bin
        } else {
            // Only open a new bin if the average residual is very small (fragmentation)
            // or if we have many items left and current bins are "polluted"
            let progress = step_index as f64 / total_items as f64;
            let fragmentation_threshold = 15.0;
            if mean_residual < fragmentation_threshold && progress < 0.9 {
                20.0 // Penalize opening new bins early
            } else {
                -5.0 // Allow opening a new bin if current bins are too full to be useful
            }
        }
    } else {
        0.0
    };

    // 5. Fitting count logic: If this is the last fitting bin, prioritize it to avoid new bins
    let scarcity_bonus = if fitting_bins_count == 1 && !is_new_bin {
        -10.0
    } else {
        0.0
    };

    score += harmonic_penalty + lookahead_bonus + new_bin_penalty + scarcity_bonus;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

