        score += 50.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: if next_item_size is known, penalize placements that prevent 
    // the next item from fitting into this bin, especially if it's the only bin left.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding: as the stream progresses, become more conservative
    // about opening new bins. 
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate score.
        // We make opening a new bin increasingly expensive as the stream nears the end.
        score += 30.0 + (progress * 40.0);

        // If there are other bins that could fit this, heavily penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 100.0 / (fitting_bins_count as f64 + 1.0);
        }
    } else {
        // For existing bins, reward alignment with the global mean residual to keep bins balanced.
        let diff = (post_res - mean_residual).abs();
        score -= 5.0 * (1.0 - (diff / bin_capacity as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #531: Harmonic Residual Optimization
    // Targets the minimization of "dead space" by penalizing post_residuals that are 
    // too small to accommodate common item sizes while rewarding those that align 
    // with lookahead expectations.

    let mut score = post_residual as f64;

    // 1. Penalty for "tight" residuals that leave small unusable gaps (1-9)
    // These are often "dead zones" in bin packing.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Harmonic Lookahead Coupling:
    // If a next item exists, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong reward for keeping the bin capable of holding the next item
            score -= 30.0;
        } else {
            // Penalty for stranding the next item if we are forced to open a new bin
            score += 15.0;
        }
    }

    // 3. Density Management:
    // Avoid creating too many open bins if the current residual is near the mean.
    // This pushes the algorithm toward Best-Fit behavior.
    let residual_delta = (bin_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.1;

    // 4. New Bin Thresholding:
    // If this is an empty bin (bin_residual == bin_capacity), make it expensive
    // unless the item fits perfectly or we have no other choice.
    if bin_residual == bin_capacity {
        score += 45.0; 
        // If it's the ONLY bin that fits, we are forced to open it anyway.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // 5. Progress Normalization:
    // As the stream nears completion, become more aggressive in packing to avoid 
    // leaving items in the final bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

