}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score: We prefer smaller post_residuals (Best Fit).
    let mut score = post_residual as f64;

    // Penalty for creating a bin that is too small for future items.
    // If we have a lookahead, penalize post_residuals that cannot fit the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 45.0 * (1.0 - progress);
    }

    // Penalty for leaving "dead space" that is too small to be useful (less than 10).
    if post_residual < 10 && post_residual > 0 {
        score += 30.0;
    }

    // Dynamic threshold: As we approach the end of the stream, prioritize 
    // filling current bins over opening new ones.
    if bin_residual == bin_capacity {
        // This is a new bin candidate. 
        // Penalize opening a new bin unless we have very few fitting bins.
        score += 25.0 + (fitting_bins_count as f64 * 15.0) + (progress * 20.0);
    } else {
        // Reward bins that have residuals close to the mean to maintain balance.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= deviation * 0.2;
    }

    // Heavily penalize opening a new bin if an existing one is a perfect fit.
    if bin_residual == bin_capacity && post_residual == 0 {
        score += 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

