    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely
    if is_new_bin {
        // Only open a new bin if we are forced to, or if the average space in current bins 
        // is so tight that it will likely cause many future items to overflow.
        // We add a penalty that decreases as the stream progresses to allow for packing flexibility.
        score += (bin_capacity as f64 - mean_residual) * (1.0 - progress) * 2.5;

        // If there are other bins that could fit this, heavily penalize opening a new one
        if fitting_bins_count > 0 {
            score += 150.0;
