        // Non-linear coupling: reward filling bins more tightly when lookahead (next_item_size) is large
        // If next_item_size is large, we want to leave the current bin with more space if possible
        // to avoid stranding the large item later.
        if next_item_size > 0 {
            let space_for_next = post_residual as f64 - next_item_size as f64;
            if space_for_next < 0.0 {
                // Penalize placements that make the next item impossible to fit here
                score += 20.0 * (1.0 - progress);
            } else {
                // Reward placements that leave exactly enough room for the next item
                score -= 10.0 * (1.0 - (space_for_next / bin_capacity as f64));
            }
        }

        // Penalize creating "dead space" (residuals < 10 are often unusable given 10..80 range)
        if post_residual > 0 && post_residual < 10 {
