        }
    } else {
        // 4. Tightness bias: Prefer bins that are already tight (Best Fit heuristic logic).
        // If this bin is the last one that can fit the item, prioritize it to keep other options open.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // 5. Progression scaling: As we approach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    // 6. Mean Residual Balancing: penalize bins that deviate significantly from the current average density.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
