    // Discourage opening a new bin (bin_residual == bin_capacity) unless forced.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 40.0 + (open_bins_count as f64 * 2.0);
        }
    }

    // 4. Tight Fit Reward: Strongly favor bins that become very full (Best Fit principle).
    // This reduces the number of bins with small, unusable residuals.
    if post_residual < 5 {
        score -= 15.0;
    }

    // 5. Mean residual equilibrium: If the current bin's post_residual is significantly 
    // better than the current mean, reward it to encourage consolidation.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 6. Progression scaling: As we approach the end of the stream, prioritize
    // closing bins (lower post_residual) to minimize remaining capacity waste.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
