    // 2. Lookahead Coupling: If next_item_size is large, prioritize bins that leave enough room for it.
    // If post_residual is smaller than next_item_size, apply a penalty proportional to the deficit.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
    }

    // 3. New Bin Thresholding: If we are forced to use a new bin, only do so if the current 
    // mean_residual of existing bins is already very small (tight packing).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 15.0 {
            score += 50.0; // Discourage opening new bins if current bins have plenty of space
        } else {
            score -= 10.0; // Otherwise, incentivize opening a new bin to keep current bins clean
        }
    }

    // 4. Scarcity Logic: If fitting_bins_count is 1, we are at a critical juncture.
    // Penalize leaving a very small, unusable residual (1-5) in the last available bin.
    if fitting_bins_count == 1 && post_residual < 6 {
        score += 20.0;
    }

    // 5. Progression Scaling: As the stream nears completion, favor filling existing bins 
    // to avoid leaving partially filled bins at the end.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (bin_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual while penalizing fragmentation (small, unusable gaps)
    // and maintaining a balance between bin utilization and open bin count.

    let mut score = post_residual as f64;

    // 1. Dead space avoidance: Penalize post_residual ranges that are typically unusable (1..9).
    // If post_residual is in (0, 10), it creates high fragmentation.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead optimization: If the next item can fit in the current post_residual, 
    // prioritize this bin heavily to avoid opening a new one later.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 3. Open bin pressure: Penalize opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), add a cost proportional to existing open bins.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Fitting constraints: If this is the only bin that can fit the item, 
    // give it a slight bonus to ensure we don't accidentally open a new bin instead.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 5. Global efficiency: Favor bins that keep the mean_residual low.
    // If this bin's post_residual is lower than the current mean, it's a good candidate.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 6. Progression scaling: As we reach the end of the stream, be more aggressive 
    // about filling existing bins to prevent leaving many partially full bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize smaller post_residual (tighter packing)
    // 2. Penalty for creating "orphaned" space: if the remaining space is small,
    //    it is likely to be wasted. Penalize ranges [1, 9] heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 3. Lookahead synergy: if the post_residual can accommodate the next item,
    //    heavily reward this bin to keep the packing density high.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0;
            // Additional reward for a near-perfect fit for the next item
            score -= (1.0 / (1.0 + (post_residual - next_item_size) as f64)) * 20.0;
        } else {
            // If we cannot fit the next item, penalize if this bin was our only option
            if fitting_bins_count == 1 {
                score += 10.0;
            }
        }
    }

    // 4. Mean Residual balancing: avoid deviating too far from the average state
    //    of open bins to prevent fragmentation across multiple bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. New Bin Threshold: if bin_residual == bin_capacity, we are evaluating a new bin.
    //    Only open a new bin if we are forced to (no fitting bins) or if current
    //    open bins are extremely fragmented (high mean_residual).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Discourage opening new bins if existing ones can fit the item
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            // Neutral score for forced new bin
            score = 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
