    // 5. Dynamic time horizon: As we approach the end of the stream, 
    // become more aggressive in packing to avoid leaving half-empty bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (100.0 - post_residual as f64) * 0.2;
    }

    // 6. Prefer bins that keep the mean residual of the system balanced.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
