    // However, we penalize tiny gaps (1-4) that are unlikely to be filled later.
    if post_residual > 0 && post_residual <= 4 {
        score += 25.0;
    }

    // 2. Lookahead compatibility:
    // If the next item fits into the post_residual, drastically lower the score.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. New bin penalty:
    // If this is a new bin (bin_residual == bin_capacity), penalize based on current utilization.
    // We only want to open a new bin if the mean_residual is very low (bins are full).
    if bin_residual == bin_capacity {
        score += 45.0 + (mean_residual * 0.5);
    }

    // 4. Scarcity management:
    // If this is the only bin that can fit the item, reward it highly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Progression bias:
    // In the later stages of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
