    if (bin_capacity as f64 - mean_residual) > current_bin_fullness as f64 {
        score -= 5.0;
    }

    // 4. Dynamic threshold for opening new bins:
    // Only open a new bin if the current fit is extremely poor (large waste).
    if bin_residual == bin_capacity {
