        // reduce penalty as we approach the end to clear out remaining items efficiently.
        score += 45.0 * (1.0 - progress).powf(0.5);

        // If we have many open bins, penalize opening another one heavily.
        score += (open_bins_count as f64) * 5.0;
    } else {
        // Reward bins that bring the mean residual closer to a "healthy" value (e.g., 20).
        // This encourages packing items into bins that are already partially filled.
        let deviation = (post_residual as f64 - 20.0).abs();
        score += deviation * 0.2;
    }

    // Final scaling: favor bins that are the only option to prevent overflow
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #601: Harmonic Residual Optimization
    // Objective: Minimize wasted space while reserving capacity for predicted next items.

    let mut score = post_residual as f64;

