        // If we have very few bins open, we are more willing to open a new one.
        score -= (open_bins_count as f64) * 2.0;
    }

    // 5. Mean Residual Balancing:
    // Penalize bins that deviate significantly from the mean_residual of other bins
    // to keep the bin distribution uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 6. Progression Scaling:
    // As we near the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
