    // 4. Global state coupling:
    // If the mean residual of current bins is high, we are already fragmented.
    // Try to consolidate by choosing bins that bring us closer to the mean.
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    // 5. Final constraint: Avoid extremely small "dead" residuals (1..5) 
    // unless it is a perfect fit (0).
    if post_residual > 0 && post_residual < 6 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
