    }

    // 5. Critical Pressure:
    // If fitting_bins_count is 1, this is the only bin that can take this item. 
    // We should prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

