    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating tiny slivers that are likely to remain empty (dead space)
    // We heavily penalize post_residuals in the (0, 10) range as they are hard to fill.
    let dead_space_penalty = if post_residual > 0 && post_residual < 10 {
        25.0 * (1.0 - (post_res / 10.0))
    } else {
        0.0
    };

    // Reward bins that leave larger residuals early in the stream, 
    // but switch to Best-Fit (minimizing post_residual) as the stream nears completion.
    // This allows for more flexibility early on and tighter packing at the end.
    let fit_optimization = post_res * (0.5 + 0.5 * progress);

    // Lookahead logic: if we know the next item, prioritize keeping space for it.
    // If the next item fits in the current post_residual, reward this placement.
    let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size {
        -15.0 * (next_item_size as f64 / bin_capacity as f64)
    } else {
        0.0
    };

    // Penalty for opening new bins: if this is a new bin (residual == capacity),
    // increase the score significantly to force the use of existing bins.
    // The penalty decreases as the stream progresses to allow for better packing towards the end.
    let new_bin_penalty = if bin_residual == bin_capacity {
        (45.0 * (1.0 - progress)) + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Combine factors
    // Lower score is better.
    fit_optimization + dead_space_penalty + lookahead_bonus + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
