    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // 5. New Bin Logic: Discourage opening a new bin unless the current empty space is poor.
    // If bin_residual == bin_capacity, we are evaluating a "New Bin".
    if bin_residual == bin_capacity {
