    // Mean residual balancing: Penalize bins that deviate significantly from the 
    // average efficiency of currently open bins.
    let residual_deviation = (post - mean_residual).abs();
    score += residual_deviation * 0.5;

    // Final scaling: favor bins that result in near-zero residuals (perfect fits)
    // using a non-linear exponential decay for the perfect fit case.
    if post_residual == 0 {
