    // 2. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty based on current open bin count.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 1.5);
