    // 1. Base penalty for creating small, unusable gaps (The "Dead-Space" avoidance)
    // If post_residual is in the [1, 9] range, it's highly unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Class Logic: Reward placements that result in "tight" bins
    // Specifically target multiples of 25 (e.g., 25, 50, 75) as they are highly divisible by common item sizes.
    let residual_mod = post_residual % 25;
    score += residual_mod as f64 * 0.5;

    // 3. Lookahead Integration: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 4. Strategic New Bin Penalty:
    // If we are considering a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // unless we have exhausted almost all existing fitting options.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one can take the item.
            score += 150.0;
        } else {
            // If no existing bin fits, normalize the new bin score to be competitive.
            score = 10.0;
        }
    }

    // 5. Global Pressure:
    // As the stream progresses, prioritize filling existing bins more aggressively to avoid trailing fragmentation.
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 20.0);

    // 6. Mean Residual Balancing:
    // Avoid bins that deviate significantly from the mean residual to keep packing density uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Avoidance: Heavily penalize post_residuals that are too small to fit any possible future item.
    // Since item sizes are >= 1, any residual < 10 is often "dead" because the minimum item size is 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Coupling: If the next item can fit in the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Penalize opening new bins when existing ones are available.
    // If this is a new bin (bin_residual == bin_capacity), add a cost proportional to existing open bins.
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Fitting Scarcity: If this is the only bin that can fit the item, give it a significant boost.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // 5. Global Efficiency: If the post_residual is close to the mean residual of other bins, 
    // it helps keep bin states uniform, reducing fragmentation.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating a new bin: if this is an empty bin, add a significant cost 
    // unless we are forced (no bins can fit the current item).
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 85.0; 
    }

    // 2. Lookahead matching: reward bins where the post_residual is close to the next_item_size.
    // This effectively creates "perfect fit" clusters for the subsequent item.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.75;
    }

    // 3. Penalty for fragmentation: penalize bins that deviate significantly from the 
    // current mean residual of all open bins. This encourages "leveling" bin usage.
    let residual_delta = (post_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.4;

    // 4. "Last Chance" optimization: If this is the only bin that can fit the item, 
    // we prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Tightness incentive: reward smaller post_residuals (Best Fit logic) 
    // but dampen it to allow the lookahead logic to override.
    score += (post_residual as f64) * 0.15;

    // 6. Progress normalization: as we approach the end of the stream, 
    // become more aggressive about filling existing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // 2. New-Bin logic: Heavily penalize opening a new bin early in the stream
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Only open a new bin if we have no other choice, or if the current bins are nearly full
        // Penalty increases as we progress through the stream
        score += 15.0 + (progress * 50.0);
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    } else {
        // 3. Lookahead coupling: If next_item_size fits in the post_residual, reward this placement
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }

        // 4. Global state coupling: Balance bins by penalizing placements that deviate 
        // significantly from the mean residual of open bins.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;

        // 5. Critical point: If this is the last chance for the current item, prioritize 
        // fitting it even if the residual is poor.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // 6. Dynamic Scaling: Penalize fragmentation as the number of open bins grows
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit)
    // We penalize large post_residual values to keep bins packed tightly.
    let mut score = post * post * 0.01;

    // Penalty for creating a bin that is too small for the lookahead item
    // If the post_residual is smaller than the next item, we create dead space.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post) * 2.5;
    }

    // Dynamic pressure: As we approach the end of the stream, prioritize 
    // filling existing bins over opening new ones to reduce the final bin count.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalty for opening a new bin scales with stream progress
        score += 45.0 * (1.0 + progress * 2.0);

        // If we have many bins already, discourage opening another
        score += open_bins_count as f64 * 0.5;
    } else {
        // Reward for keeping the mean residual low
        // If this bin is already emptier than average, prioritize filling it
        if post_residual as f64 > mean_residual {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // Critical constraint: If this is the last chance to fit the item in an existing bin,
    // apply a significant discount to favor it over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Reward Best Fit / Tight packing: Minimize the post_residual
    // This naturally favors bins that leave the least space.

    // 2. Penalty for creating "Dead Zones":
    // If the remaining space is too small for any likely future item (e.g., < 10),
    // we penalize it unless it's perfectly zero (a perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead logic:
    // If the next item can fit into the current post_residual, reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // 4. Harmonic consideration for empty bins:
    // When considering opening a new bin (bin_residual == bin_capacity),
    // apply a cost based on how many bins are already open to discourage fragmentation.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin is proportional to the current bin count
        score = 45.0 + (open_bins_count as f64 * 0.5);

        // If we have many open bins that could have taken this item, punish opening a new one
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 10.0;
        }
    }

    // 5. Residual utilization:
    // If the post_residual is a multiple of common item sizes (20, 25, 50),
    // it is more likely to be filled later. Reward these "harmonic" remainders.
    if post_residual > 0 && (post_residual % 20 == 0 || post_residual % 25 == 0) {
        score -= 5.0;
    }

    // 6. Progress-based scaling:
    // Towards the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post_residual (Best Fit principle).
    let mut score = post_residual as f64;

    // 1. DEAD SPACE PENALTY: Heavily penalize post_residuals that are small but 
    // too large to be useful (e.g., 1-9 range where few items fit).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. LOOKAHEAD COUPLING: If the next item cannot fit in the current post_residual,
    // penalize this placement to keep the bin open for a potential better fit later.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. OPEN BINS PRESSURE: If this is an empty bin, penalize it based on how many
    // bins are already open. This discourages opening new bins unless necessary.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
        // As we approach the end of the stream, lower the barrier to open new bins.
        score -= (progress * 20.0);
    }

    // 4. FRAGMENTATION AVOIDANCE: Penalize placements that make the residual 
    // deviate significantly from the mean residual of open bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. URGENCY: If this is the only bin that fits the current item, 
    // lower the score to ensure we don't accidentally open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for opening a new bin:
    // If this is a new bin (residual == capacity), add a significant bias to encourage filling existing ones.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 45.0;
    }

    // 2. Lookahead synergy: 
    // Reward bins where the post_residual is a near-perfect fit for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect or near-perfect match (0-5 gap) gets a strong reward.
            let diff = (post_residual - next_item_size) as f64;
            score -= (25.0 / (1.0 + diff)) * 2.0;
        } else {
            // Penalty if the next item cannot fit in this bin after current placement.
            score += 15.0;
        }
    }

    // 3. Efficiency heuristic:
    // Penalize placements that create "dead space" (very small residuals that are hard to fill).
    // If post_residual is < 10, it is likely unusable for future items (range 10-80).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 4. Mean residual balancing:
    // Prefer bins that stay close to the current mean residual to keep bin fullness uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 5. Urgency factor:
    // If this is the only bin that can fit the item, prioritize it to avoid forced new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Progression scaling:
    // As we approach the end of the stream, prioritize aggressive packing (lower residuals).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a 'sliver' (unusable space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Best-Fit Decreasing logic: favor bins that leave minimal space
    // We normalize this by the current bin_residual to prioritize tight fits
    score += (bin_residual as f64 - item_size as f64) * 0.1;

    // Lookahead: if the next item is large, avoid bins that leave little space for it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        } else {
            // Reward bins that can accommodate the next item
            score -= (100.0 - post_residual as f64) * 0.2;
        }
    }

    // Global state: if we have many bins open, penalize opening a new one
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 2.0);
        // Late game: be more aggressive in packing to prevent new bin openings
        score += progress * 20.0;
    }

    // Fitting constraint: if this is the only bin that fits the item, make it very attractive
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Density optimization: favor bins closer to the mean residual to keep distribution uniform
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize Best-Fit (smaller post_residual is better)
    let mut score = post;

    // Penalty for creating 'dead space' (small residuals that are hard to fill)
    // We penalize post_residuals that are too small to fit common items (e.g., < 10)
    // but larger than 0.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: if a future item exists, reward bins that can accommodate it.
    // If next_item_size fits in the post_residual, reduce the score.
    if next_item_size > 0 && (post_residual >= next_item_size) {
        score -= 15.0 * (1.0 - progress);
    }

    // New bin avoidance: If there are other bins that could fit this item,
    // penalize opening a new bin (where bin_residual == bin_capacity).
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 50.0 * (1.0 + progress);
    }

    // Global density control: If we are deep into the stream, try to keep 
    // the mean residual low to avoid fragmentation.
    if open_bins_count > 0 {
        score += (mean_residual - post) * progress;
    }

    // Non-linear coupling: penalize high fragmentation as the stream progresses
    score += (post * post) / (bin_capacity as f64 * (1.1 - progress));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize smaller post_residual (Best Fit).
    // Penalize large post_residual (wasted space) quadratically.
    score += (post_residual as f64).powi(2) * 0.05;

    // 2. Harmonic Class logic:
    // If post_residual is very small, it might be "too tight", making it hard to fit future items.
    // If post_residual is a factor of the capacity, it's often a good alignment.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // Moderate penalty for "slivers" that are too small for most items
    }

    // 3. Lookahead Integration:
    // If next_item_size fits in the current post_residual, reward this bin heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 4. Fitting Constraint:
    // If this is the only bin that can fit the item, we must prioritize it unless
    // the post_residual is extremely poor.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // 5. Global Bin Management:
    // Penalize opening a new bin (where bin_residual == bin_capacity) 
    // unless the mean_residual is already very low (indicating we are packing tightly).
    if bin_residual == bin_capacity {
        score += 25.0 + (mean_residual * 0.5);
    }

    // 6. Progression Weighting:
    // As we approach the end of the stream, prioritize closing bins (minimizing open_bins_count).
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "Dead Space" (gaps too small to fit the smallest expected items)
    // We heavily penalize post_residuals in the [1, 9] range as they are likely wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead optimization: If the next item can fit in the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open bins pressure: If this is an existing bin, penalize it if we have too many open bins.
    // This encourages filling existing bins rather than spreading items thin.
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * 0.5;
    }

    // 4. New bin threshold: If this is a new bin (bin_residual == bin_capacity), 
    // only select it if the fitting_bins_count is low or the residual pressure is high.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if we have existing options
            score += 45.0 + (fitting_bins_count as f64 * 5.0);
        } else {
            // Must open a new bin
            score = 0.0;
        }
    }

    // 5. Mean residual balancing: Favor bins that keep the mean residual closer to the global average
    // to keep bin utilization uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
