        score += 45.0;
    }

    // 2. Best-Fit-Decreasing influence: reward tighter fits.
    // If we have many options, prioritize the one that leaves the least space.
    score += (post_residual as f64) * 0.1;

    // 3. Lookahead Matching: If post_residual perfectly accommodates the next item,
