        } else {
            // Penalty if we make a bin too small to fit the next item
            score += 15.0;
        }
    }

    // 4. Mean Residual balancing: Avoid creating bins that are outliers.
    // If current mean_residual is low, prioritize keeping this bin's residual near that average.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.05;

    // 5. Urgency factor: If this is the only bin that fits, we are forced to take it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Progress-based scaling: As the stream nears the end, prioritize closing bins
