}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best-Fit Penalty: Minimize residual space (standard Best-Fit logic)
    // We favor bins where post_residual is small (near 0)

    // 2. Lookahead Penalty: If a future item fits perfectly in the current post_residual, 
    // prioritize this bin. If the current post_residual is too small for the next item, 
    // it's a "bad" fit.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.8;
        } else {
            score += (bin_capacity - post_residual) as f64 * 0.5;
        }
