    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // 6. Penalty for creating "stranded" space (bins that are very hard to fill later)
    // If post_residual is between 1 and 9, it's very likely to become unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

