    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // 1. Base Score: The post-placement residual (Best-Fit principle).
    // Smaller post-residual is better (lower score).
    let mut score = post_residual as f64;

    // 2. Penalize new bin creation heavily, but allow it if current fitting bins are inefficient.
    if is_new_bin {
        // If we have fitting bins, opening a new one is usually bad.
        // We only open if the current fitting bins are very tight or we are early in the process.
        score += 45.0 + (progress * 20.0);
    }

    // 3. Lookahead Logic (k=2):
    // If we have a next item, penalize bins that cannot fit the next item after this one.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize creating "dead zones" that can't fit the next item.
            score += 25.0 * (1.0 - progress);
        } else {
            // Reward bins that can accommodate the next item (synergy).
            score -= 10.0 * (1.0 - progress);
        }
    }

    // 4. Global State Adjustments:
    // If we have many open bins, we need to be more aggressive about filling existing ones
    // rather than opening new ones or keeping many bins half-empty.
    if open_bins_count > 0 {
        let mean_utilization = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
        // If mean utilization is low, penalize leaving large residuals.
        if mean_utilization < 0.5 {
            score += (post_residual as f64) * 0.5;
        }
    }

    // 5. Criticality check:
    // If this is the only bin that can fit the item, prioritize it highly (lower score).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (lower post_residual)
    let mut score = post_res;

    // Penalty for creating 'dead space' (bins left with small unusable residuals)
    // We penalize residuals that are too small to fit typical future items (e.g., < 20)
    if post_res > 0.0 && post_res < 20.0 {
        score += (20.0 - post_res) * 2.5;
    }

    // Lookahead logic: if next item is large, favor keeping bins open that can accommodate it
    if next_item_size > 60 {
        score += (100.0 - post_res) * 0.5;
    }

    // Dynamic pressure: as the stream progresses, become more aggressive in packing
    // (reducing the penalty for opening new bins or choosing imperfect fits)
    let tightness_factor = 1.0 + (progress * 2.0);
    score *= tightness_factor;

    // If this is the only bin that can fit the item, prioritize it to avoid wasting a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Discourage opening a new bin unless the current residual is highly inefficient
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate call
        // Only open if current bins are very full or if we are late in the stream
        score += (open_bins_count as f64 * 10.0) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that leave the smallest residual.
    // However, we apply a penalty to very small residuals that create "dead space" 
    // too small for any likely item (e.g., < 10).
    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    }

    // 2. Harmonic Class Logic: Reward placements that result in residuals which are
    // multiples of common item sizes (e.g., 20, 25, 33). This prepares the bin 
    // for future items.
    if post_residual > 0 {
        let remainder = post_residual % 25;
        score += (remainder as f64) * 0.5;
    }

    // 3. Lookahead Logic: If the next item fits into the current post_residual, 
    // highly incentivize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. New Bin Threshold: If we are forced to open a new bin, penalize it 
    // based on the current mean_residual to prevent opening new bins when 
    // existing bins have plenty of space.
    if bin_residual == bin_capacity {
        score += mean_residual * 0.8;
        // If there are other bins that could have fit this item, make opening 
        // a new bin very expensive.
        if fitting_bins_count > 0 {
            score += 150.0;
        }
    }

    // 5. Progression Bias: As the stream nears completion, become more aggressive 
    // about packing into existing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

