    // We penalize residual space ranges that are too small for common items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, reward this bin placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins if we have many already open.
    // Only apply when evaluating the NEW-BIN candidate (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;

        // If we are late in the stream, penalize opening new bins more heavily to encourage consolidation.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that can fit the current item, 
    // prioritize it heavily to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Residual Balance: Penalize bins that deviate significantly from the mean residual
    // to keep open bins packed at similar levels (Best-Fit-like behavior).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Heavily favor bins where post_residual is small (tight fit).
    // The base score is already post_residual, which naturally implements Best-Fit.

    // 2. Lookahead Synergy: If the next item fits into the current bin's remaining space,
    // we prioritize this bin to maximize bin density (Best-Fit Decreasing logic).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Fragmentation Avoidance: If post_residual is too small to fit common items,
    // it becomes "dead space." Penalize post_residuals that are between 1 and 9.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 4. Global Density Balancing: Compare the target bin's residual against the mean.
    // If the bin is emptier than the average, we penalize it to prevent spreading 
    // items too thin across many bins.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 5. New Bin Logic: Discourage opening a new bin unless the current residual 
    // constraints are extremely poor. 
    if bin_residual == bin_capacity {
        // Only pick a new bin if we have no options or if the current stream 
        // is in the early stages where we want to keep options open.
        if fitting_bins_count > 0 {
            score += 40.0;
        } else {
            score -= 10.0;
        }
    }

    // 6. Urgency: As we approach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (open_bins_count as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
