    // it creates "dead space". We penalize this heavily to encourage tighter packing.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // This bin becomes useless for the next item, penalize significantly
            score += (next_item_size - post_residual) as f64 * 2.5;
        } else {
            // Reward bins that can perfectly or nearly accommodate the next item
            let fit_slack = post_residual - next_item_size;
            score -= (100.0 - fit_slack as f64) * 0.5;
        }
    }

    // 3. Balance towards mean residual to keep bins uniform
    // If the current bin's post_residual is significantly better than the global average, favor it.
    let residual_delta = post_residual as f64 - mean_residual;
    score += residual_delta * 0.2;

    // 4. Progression scaling: As we approach the end of the stream, prioritize 
    // exhausting existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 50.0;
    }

    // 5. Final penalty for creating small, hard-to-fill gaps (the "fragmentation" penalty)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
