    let deviation_penalty = (post - mean_residual).abs() * 0.5;

    // Final score: lower is better. 
    // We add the new_bin_penalty to the base tightness and lookahead metrics.
    new_bin_penalty + tightness_score + lookahead_effect + deviation_penalty
}

