    // Reward bins that have residuals close to the global mean (promotes uniform packing).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // Favor bins that have less space remaining (Best Fit principle).
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Strategy: Best Fit (minimize post_residual).
    // 2. Penalty for opening new bins prematurely:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless the current number of open bins is very small.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 0.5);
    }

    // 3. Lookahead Logic: 
    // If this bin's post_residual can perfectly or nearly perfectly accommodate the next item,
    // give it a strong preference.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            // Reward bins that leave just enough space for the next item
            score -= (10.0 / (1.0 + (post_residual - next_item_size) as f64));
        }
    }

    // 4. Balancing:
    // Avoid creating "islands" of small space. If post_residual is small (e.g., < 10),
    // it is unlikely to fit future items. Penalize this unless it's a perfect fit.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // 5. Global state normalization:
    // As the stream progresses, prioritize closing bins to reduce open_bins_count.
    // If fitting_bins_count is 1, this is the only bin that can take the item, 
    // so we should make it very attractive to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Mean Residual Adjustment:
    // If this bin's post_residual is significantly better than the global mean, favor it.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Decreasing logic: Favor bins that minimize post_residual.
    // Penalty for creating "slivers" (very small residuals that are hard to fill).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead optimization: If a future item exists, prioritize bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that can hold the next item
        } else if post_residual < 10 && post_residual > 0 {
            score += 10.0; // Penalize bins that leave no room for the lookahead
        }
    }

    // 3. Global state balance: If we have many open bins, penalize opening new ones.
    // Use the mean_residual to identify if existing bins are generally "full" or "empty".
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // High penalty for new bin if we have many bins with decent space
        score += (open_bins_count as f64 * 5.0) + (100.0 - mean_residual);
    } else {
        // Reward using existing bins, specifically those closer to the mean residual
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score -= deviation * 0.1;
    }

    // 4. Dynamic thresholding: Near the end of the stream, be more conservative with new bins.
    if is_new_bin && progress > 0.8 {
        score += 40.0 * (progress - 0.8) / 0.2;
    }

    // 5. Fitting count constraint: If this is the only bin that fits the current item, 
    // it is highly valuable regardless of post_residual.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space; we want to minimize this (Best Fit principle).
    let mut score = post;

    // Penalty for creating a "sliver" (fragmentation) that is too small for common items.
    // We penalize post_residual values below 10 (the minimum item size).
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Dynamic Lookahead Coupling: 
    // If the next item exists, we penalize bins that cannot accommodate it,
    // weighted by how far we are into the stream.
    if next_item_size > 0 {
