    if bin_residual == bin_capacity {
        let open_bin_cost = 25.0 + (progress * 20.0) + (mean_residual * 0.5);
        score = open_bin_cost;
    } else {
        // Favor bins that align with the global average residual to keep bin levels balanced.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.2;
    }

    // If this is the only bin that can fit the item, give it a significant priority boost
    // to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating a "sliver" (fragmentation)
    // Avoid leaving small gaps that are unlikely to fit future items (e.g., < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Harmonic preference: reward residuals that are multiples of common item sizes
    // This maximizes the chance of fitting future items perfectly.
    let mod_val = (post_residual % 20) as f64;
    score += mod_val * 0.5;

    // Lookahead logic: if the next item fits into the current post_residual,
    // strongly prioritize this bin (Best-Fit-Decreasing logic).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
        // Further refine: prefer tightest fit for the lookahead
        score += (post_residual - next_item_size) as f64 * 0.2;
    }

    // If this is a new bin (bin_residual == bin_capacity), penalize it relative to fitting_bins_count.
    // We only want to open a new bin if the existing options are poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if others exist
            score += 60.0 + (fitting_bins_count as f64 * 5.0);
        } else {
            // Base cost for opening a new bin when no others fit
            score -= 10.0;
        }
    }

    // Density normalization: prefer bins that are closer to being filled
    // as the stream progresses.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - (bin_capacity - post_residual) as f64 / bin_capacity as f64) * 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is too small to fit any common item (e.g., < 10),
    // it creates "fragmentation". We penalize this heavily unless it is zero (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64).sqrt();
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (next_item_size as f64 / bin_capacity as f64);
