    // 3. Bin Count Pressure: Penalize opening new bins heavily as the stream progresses.
    // If this is a new bin (bin_residual == bin_capacity), increase the cost.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 40.0 * (1.0 + progress) + (open_bins_count as f64 * 2.0);
    } else {
        // 4. Density Balancing: Favor bins that stay near the mean residual to keep bins
        // filled at similar rates, preventing "straggler" bins.
        let deviation = (bin_residual as f64 - item_size as f64) - mean_residual;
        score += deviation.abs() * 0.5;
    }

    // 5. Last Chance Logic: If this is the only bin that can fit the item, give it a massive
    // discount to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

