    // Lower residual = tighter fit = better.
    let mut score = post_residual as f64;

    // Penalty for creating a new bin: only open a new bin if the current 
    // "tightness" of existing bins is poor and we are late in the stream.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if existing bins can take the item.
            score += 150.0 + (mean_residual * 2.0);
        } else {
            // If no existing bin fits, this is the baseline for opening a new one.
            score = 50.0;
        }
    } else {
        // Reward bins that become "perfect" or near-perfect fits.
        if post_residual == 0 {
            score -= 20.0;
