        }

        // Lookahead: if the next item can fit in the post_residual, reward this bin.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0 * (1.0 - progress);
        }

        // If the current bin is becoming very empty (large residual), penalize it 
        // to encourage consolidating items into fuller bins.
        if post_residual > 40 {
            score += (post_residual as f64) * 0.5;
        }
    }

    // Dynamic pressure: as we approach the end of the stream, prioritize space efficiency.
    score += (progress * 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
