    score += harmonic_alignment * 0.5;

    // 4. Global Density Control: If fitting_bins_count is 1, we are at a critical decision point.
    // If the residual is quite large, force a new bin to keep density high in the existing one.
    if fitting_bins_count == 1 && post_residual > 30 {
        score += 25.0;
    }

