    // The penalty for a residual r is high if r < 10 (the minimum item size).
    let dead_space_penalty = if post_residual < 10 && post_residual > 0 {
        100.0 / (post + 1.0).powf(0.5)
    } else {
        0.0
    };

    // If this is the only bin that can fit the item, we lower its score to ensure it is picked
