    let mut score = (post * progress_scaling) + dead_space_penalty + fitting_urgency + lookahead_reward;

    // Discourage opening new bins (bin_residual == bin_capacity) unless necessary.
    // If the bin is brand new, add a significant penalty that decreases as the stream progresses
    // (allowing for more empty bin starts if the current packing density is poor).
    if bin_residual == bin_capacity {
