    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight fits.
    // We favor bins where post_residual is minimal (Best Fit).

    // 2. Lookahead Integration: If next_item_size fits in the current post_residual, 
    // heavily reward this bin to prevent fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. New Bin Thresholding: Discourage opening a new bin unless the current 
    // mean_residual is already very low or we are near the end of the stream.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if other bins can fit the item
            score += 100.0 * (1.0 - progress);
        } else {
            // Necessary to open a new bin
            score -= 50.0;
        }
    }

    // 4. Global State Calibration: If the average residual is high, we are 
    // currently wasting space; prioritize filling existing bins aggressively.
    if mean_residual > 20.0 {
        score += (mean_residual - 20.0) * 0.5;
    }

    // 5. Fragmentation Avoidance: If post_residual is small but > 0, it creates 
    // a "sliver" (unusable space). Penalize slivers (e.g., < 10) unless it's a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 6. Dynamic Scaling: As we approach the end of the stream, prioritize 
    // clearing out open bins over maintaining space for future items.
    score -= progress * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize opening new bins heavily early in the stream, but allow flexibility as the stream ends.
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = if is_new_bin {
        // New bin penalty: High early on, lower as we approach the end to avoid fragmentation.
        15.0 + (30.0 * (1.0 - progress).powf(2.0))
    } else {
        // Base score is the post_residual (Best Fit principle).
        post_res
    };

    // Coupling: If we have a lookahead, penalize high post_residuals that would orphan the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // This placement creates a gap too small for the next item; penalize based on wasted space potential.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Heuristic: Prefer bins that bring the bin towards the mean_residual (balancing load).
    let deviation = (post_res - mean_residual).abs();
    score += deviation * 0.1;

    // Favor bins that are "tight" (low post_residual) but avoid making them "useless" (near 0, but not 0).
    // Extreme tight fits (post_residual < 5) are very desirable.
    if !is_new_bin && post_residual < 5 {
        score -= 10.0;
    }

    // If this is the only bin that fits, prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

