        }
    }

    // 3. Density Balancing: Favor bins with lower residuals to keep them packed tight.
    // If post_residual is low, we reward the bin to encourage "Best Fit" behavior.
    score += (post_residual as f64 * 0.1);

    // 4. Lookahead/Progression: As the stream nears the end, favor tighter packing 
    // to avoid leaving many bins half-full.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    // 5. Mean Residual Coupling: Discourage bins that deviate significantly from 
    // the current average fullness of open bins to maintain homogeneity.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
