        score -= 50.0;
        // Further refine: favor the tightest fit that still accommodates the next item
        score += (post_residual - next_item_size) as f64 * 0.5;
    }

    // 4. Threshold Logic: If this is the only bin that fits the current item (fitting_bins_count == 1),
    // we should prioritize using it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // 5. New Bin Penalty: If this is a new bin (bin_residual == bin_capacity), 
    // only choose it if the existing bins are poor fits.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if the item is large.
        score += 25.0 + (open_bins_count as f64 * 0.5);
    }

    // 6. Distributional Smoothing: Adjust based on progress to avoid opening new bins late in the stream.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.9 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual ranges that are typically unusable (1..9).
    // Small residuals are "traps" that likely lead to stranded capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64).sqrt();
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 3. Open Bins Pressure: Penalize opening new bins, but scale by how much "room" 
    // is left in existing bins. If we have many open bins, prioritize filling them.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have many open bins that are mostly empty.
        score += (open_bins_count as f64) * 15.0;
    } else {
        // Reward filling existing bins that are already below the mean residual to consolidate.
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // 4. Criticality: If this is the only bin that can fit the item, prioritize it 
    // heavily to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Progression Scaling: As the stream nears completion, become more aggressive 
    // about minimizing the number of bins (penalize new bins more).
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
