        // opening a new one unless the fit is extremely tight elsewhere.
        if fitting_bins_count > 0 {
            score += 60.0;
        }
    }

    // Balance the usage of open bins: penalize bins that deviate too far from the mean_residual
    // to encourage keeping bins at similar fullness levels (load balancing).
    let deviation = (post - mean_residual).abs();
    score += 0.5 * deviation;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

