    }

    // 4. Balance the packing: favor bins that stay close to the current mean_residual
    // This encourages uniform bin usage rather than fragmentation.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.2;

