    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // Adaptivity: As the stream nears completion, become more aggressive in packing
    // to avoid leaving too many bins half-empty.
    let density_pressure = (mean_residual / bin_capacity as f64) * progress * 50.0;
    score += density_pressure;

    // Penalty for opening new bins: if this is a new bin (bin_residual == bin_capacity)
    // we apply a high penalty that decays as the stream progresses (to allow cleanup at the end)
    if bin_residual == bin_capacity {
        score += 85.0 * (1.0 - progress * 0.5);
    }

    // If this is the only bin that fits the item, prioritize it to avoid creating a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalty for creating a bin with a residual that is too small for any future item (if known)
    // or just generally awkward for the distribution.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

