        // reward it significantly.
        if post_residual < 5 {
            score -= 20.0;
        }

        // If the current bin is "cluttered" (high mean_residual), 
        // reward placing items here to avoid opening more bins.
        if mean_residual > 30.0 {
            score -= 5.0;
        }
    }

    // 5. Dynamic Time Horizon: 
    // Towards the end of the stream, prioritize tight fits more aggressively
    // to minimize the final bin count.
    if progress > 0.8 {
        score += (post_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: Favor smaller post_residual (Best Fit)
    // We apply a non-linear penalty for leaving large gaps (wasted space)
    let mut score = post * post * 0.01;

    // Lookahead logic: If the next item fits into the current post_residual, 
    // heavily reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 * (1.0 - progress);
    }

    // Dynamic thresholding: As the stream progresses, become more conservative 
    // about opening new bins. If this is a new bin, penalize it based on progress.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin increases as we approach the end of the stream
        score += 25.0 + (progress * 50.0);
    } else {
        // If this bin is already open, reward it based on how close the 
        // post_residual is to the mean_residual of other bins (clustering)
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.5;
    }

    // Penalty for creating 'dead space' (bins that are too small to fit anything useful)
    // If post_residual is < 10, it is likely unusable for future items (10..80 range)
    if post_residual < 10 {
        score += 15.0;
    }

    // If this is the last chance for the current item (only 1 bin fits it),
    // reduce the score to force selection of this bin over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, penalize it heavily to prioritize existing space.
    // However, if fitting_bins_count is 0, we must open a new bin.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            return 0.0;
        }
        score += 85.0; 
    }

    // 2. Harmonic/Modulo logic: Favor residuals that are multiples of common item sizes (e.g., 20, 25, 33).
    // This creates "bins" that are likely to accept future items perfectly.
    let residual_mod = (post_residual % 25) as f64;
    score += residual_mod * 0.4;

    // 3. Lookahead logic: If the next item fits in the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.6;
    }

    // 4. Tightness penalty: Small residuals are often "dead space". 
    // If post_residual is < 10, it's very hard to fill.
    if post_residual < 10 {
        score += 15.0;
    }

    // 5. Global state normalization: If we have many open bins, prioritize closing the ones 
    // that are already nearly full (Best-Fit behavior).
    if open_bins_count > 0 {
        let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= tightness * 5.0;
    }

    // 6. Avoid fragmented bins: If the bin residual is significantly below the mean, 
    // penalize it to force consolidation.
    if (bin_residual as f64) < (mean_residual * 0.5) {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

