    // for future items, so we penalize it heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Synergy: If the next item fits in the current post_residual, 
    // reward this bin to keep the bins packed tightly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bins Pressure: Penalize opening a new bin (bin_residual == bin_capacity) 
    // unless the open_bins_count is very low, or the current fit is extremely poor.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64 * 2.0);
    }

