    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Global Efficiency: If the current bin is significantly emptier than the mean,
    // penalize it to encourage filling existing "fuller" bins first.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    }

    // 6. Final scaling based on progress: As we near the end, prioritize 
    // closing bins over balancing, so reduce penalty for tight fits.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We already start with score = post_residual.

    // 2. Lookahead Synergy: If the next item fits perfectly into the remaining space, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        // Reward small gaps that perfectly match the next item (e.g., gap of 0 is ideal).
        score -= (100.0 - gap as f64) * 0.5;
    }

    // 3. Fragmentation Penalty: Penalize creating "unusable" space (e.g., < 10).
    // Given item sizes are 10..80, a residual < 10 is effectively dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. Mean-Residual Balancing: Avoid bins that deviate significantly from the global mean.
    // This helps maintain a uniform distribution of fill levels across all open bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.25;

    // 5. New Bin Thresholding: 
    // If this is a new bin (bin_residual == bin_capacity), only pick it if current fits are poor.
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean_residual of existing bins is already tight (< 15)
