    // If this is the last chance for this item, reduce the penalty for a new bin slightly
    // to avoid forcing it into a very poor fit in an existing bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // 1. Base cost: The remaining space (post_residual). Smaller is better (Best Fit).
    let mut score = post_residual as f64;

    // 2. Lookahead penalty/reward:
    // If the next item fits into the post_residual, we heavily reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Fragmentation penalty:
    // If the post_residual is small but > 0, it is often "dead space" that cannot fit typical items.
    // Penalize post_residual values in the (0, 10) range significantly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Mean-matching:
    // If the post_residual is significantly lower than the mean_residual of other bins,
    // we are packing this bin tighter than average, which is generally efficient.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    }

    // 5. New Bin Logic:
    // If this is a new bin, penalize it based on how many bins are already open.
    // Only open a new bin if the current open bins are all very poorly suited for the current item.
    if bin_residual == bin_capacity {
        // High constant penalty for opening a new bin.
        score += 45.0;

        // If there are bins that could have fit the item, penalize opening a new one further.
        if fitting_bins_count > 0 {
            score += 30.0 * (fitting_bins_count as f64);
        }
    }

    // 6. Progress weighting:
    // As we approach the end of the stream, prioritize clearing bins (tighter fit).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize creating "dead space" (small residuals that are hard to fill).
    // Residuals in the range [1, 9] are extremely difficult to fill given item sizes [10, 80].
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // Lookahead logic: If the next item can fit in the current post_residual, 
    // prioritize this bin to preserve future capacity.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // Global state awareness: If we have many open bins, penalize opening a new one.
    // If fitting_bins_count is 0, this call is for a new bin.
    if fitting_bins_count == 0 {
        score += (open_bins_count as f64 * 2.0);
    } else {
        // If we are choosing between existing bins, prefer those that bring 
        // the average residual closer to a "healthy" value (e.g., ~20).
        let target_residual = 20.0;
        score += (post_residual as f64 - target_residual).abs() * 0.5;
    }

    // Progression awareness: As we approach the end of the stream, prioritize 
    // packing tighter even if it creates slightly awkward residuals.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // Penalty for empty bin usage: Only open a new bin if the score is significantly 
    // better than existing options (e.g., if existing options are all very poor fits).
    if bin_residual == bin_capacity {
        score += 30.0; 
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize new bin creation (bin_residual == bin_capacity) increasingly as we approach the end of the stream
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post * (1.0 + 0.5 * (1.0 - progress));

    // If fitting_bins_count is 1, this is the last chance for this item in an existing bin.
    // We heavily discount this to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // Lookahead logic: if next_item_size is large, favor bins that leave enough room for it.
    // We penalize post_residual if it is too small to accommodate the predicted next item.
    if next_item_size > 0 {
        let gap_penalty = if post < next_item_size as f64 {
            (next_item_size as f64 - post) * 2.0
        } else {
            // Reward bins that leave a "perfect" fit for the next item
            -(post - next_item_size as f64).abs().powf(0.5)
        };
        score += gap_penalty;
    }

    // Penalize bins that deviate significantly from the mean residual of open bins
    // to encourage uniform packing density.
    let density_penalty = (post - mean_residual).abs() * 0.2;
    score += density_penalty;

    // Discourage opening new bins unless the current best fit is extremely inefficient (high post_residual).
    if is_new_bin {
        score += 45.0 + (progress * 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
