    // If post_residual is in (0, 10), it's highly likely to be wasted.
    if post_residual > 0 && post_residual < 15 {
        score += 40.0 * (1.0 - (post_residual as f64 / 15.0));
    }

    // Reward bins that can accommodate the next item (Lookahead logic).
    // If the current bin can perfectly fit the next item after this one, prioritize it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
