    if bin_residual == bin_capacity {
        score += 35.0;
        // Reduce the penalty if we have many open bins already, 
        // to prevent over-packing a single bin when it's inefficient.
        score -= (open_bins_count as f64 * 0.5).min(10.0);
    }

    // Harmonic Class Logic: Reward residuals that align with common item size distributions.
    // Items often appear in ranges; favoring residuals that are multiples of 20 
    // helps keep bins flexible for future arrivals.
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // Adaptivity: As the stream progresses, prioritize closing bins (lower mean_residual).
    // If the current bin's residual is significantly lower than the mean, it's a good candidate.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Final threshold: If this is the last fitting bin, prioritize it to avoid new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
