    // if the average residual is already high.
    if open_bins_count as f64 > (100.0 / (100.0 - mean_residual + 1.0)) {
        score += 5.0 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Prioritize Best-Fit: penalize large post_residual values
    // We aim for post_residual == 0 (perfect fit)
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic: penalize bins that leave behind "unusable" space.
    // If post_residual is small but > 0, it creates "dead" space if it's smaller than 
    // the minimum possible item size (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead Logic: If the next item fits into the current post_residual, 
    // reward this bin heavily to create a "double-pack" effect.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
    }

    // 4. New Bin Thresholding: 
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless fitting_bins_count is very low, forcing consolidation.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 0.5);
    } else {
        // Encourage using existing bins that have a residual close to the mean
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 5. Progression Scaling: 
    // As we approach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residuals that are too small to fit common items (below 10)
    // but large enough to be wasteful. If post_residual is in (0, 10), it's likely "dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
