    }

    // 5. Urgency: As the stream nears the end, become more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (100.0 - post_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize minimizing post_residual (Best-Fit principle).
    // The base score is the post_residual itself.

    // 2. Lookahead Synergy: If the post_residual is close to the next_item_size, 
    // prioritize this bin to create a "perfect" follow-up fit.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward cases where post_residual is just enough for the next item (post_residual >= next_item_size).
        if post_residual >= next_item_size {
