    // higher than the current mean_residual to prevent fragmentation.
    if bin_residual != bin_capacity {
        score += (post_residual as f64 - mean_residual).max(0.0) * 0.8;
    }

    // 4. Scarcity/Necessity: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. New Bin Control: Set a threshold for opening a new bin. 
    // If we are considering a new bin (bin_residual == bin_capacity),
    // make it expensive unless the best fit is extremely poor.
    if bin_residual == bin_capacity {
        score += 40.0;
        // If we are late in the stream, be more conservative about opening new bins.
        score += (step_index as f64 / total_items as f64) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
