    let mut score = post;

    // Penalty for creating a 'dead zone' (residual space too small for any future item).
    // If post_residual is < 10, it is likely unusable for any incoming item (10-80 range).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if next_item_size is large, prioritize bins that can still fit it.
    if next_item_size > 0 {
