        } else {
            score += 15.0;
        }
    }

    // Dynamic density management:
    // As the stream progresses, favor packing tighter (lower mean_residual) to reduce open_bins_count.
    score += (mean_residual * progress) * 0.5;

    // New bin bias: 
    // Only open a new bin if the current fit is extremely poor (post_residual is high) 
    // or if we are forced to (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: decreases as we pack more efficiently.
        score += 25.0 + (open_bins_count as f64 * 0.1);
    } else {
        // Reward for using existing bins, scaled by how many other options exist.
        score -= (fitting_bins_count as f64).ln() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
