        }
    }

    // 3. Global State Balancing: Use mean_residual to penalize bins that deviate from the average.
    // This encourages uniformity in bin fill rates.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    // 4. Scarcity Penalty: If this is the only bin that fits, prioritize it heavily (Negative score).
    if fitting_bins_count == 1 && bin_residual >= item_size {
