    // space for the next item or create a "tight" fit.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward perfect fit for the next item
            if post_residual == next_item_size {
                score -= 25.0;
            } else {
                // Penalize wasted space that could have been used by next_item_size
                score += (post_residual - next_item_size) as f64 * 0.5;
            }
        } else {
            // If the next item cannot fit, we favor leaving a larger remainder 
            // if it helps bring the bin closer to the global mean_residual.
            let diff = (post_residual as f64 - mean_residual).abs();
            score += diff * 0.2;
        }
    }

    // Progression awareness: As we approach the end of the stream, prioritize 
    // filling bins completely over keeping them balanced.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.3;
    }

    // Final constraint: If this is the only bin that fits, heavily favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual: The space left in this bin after placing the item.
    // Lower post_residual is generally better (Best-Fit principle).

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize creating "dead space" (small, unusable remnants)
    // If post_residual is small but > 0, it's often better to have it larger 
    // to accommodate future items, or 0.
    if post_residual > 0 && post_residual < 15 {
        score += 25.0 * (1.0 - (post_residual as f64 / 15.0));
    }

    // 2. Lookahead optimization: If we know the next item, penalize if this 
    // placement makes it impossible to fit the next item in this bin.
    if next_item_size > 0 && post_residual < next_item_size {
        // Only penalize if there are other bins that could have taken it
        if fitting_bins_count > 1 {
            score += 15.0 * (1.0 - progress);
        }
    }

    // 3. Global State: Encourage filling bins that are already "below average" 
    // in remaining capacity to keep the variance of residuals low.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    // 4. New Bin Logic: If bin_residual == bin_capacity, we are evaluating a new bin.
    // Only open a new bin if the current "best fit" leaves a very awkward residual
    // or if we are nearing the end of the stream.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score = 45.0 + (20.0 * progress);

        // If we have many open bins that are nearly empty, don't open another.
        if open_bins_count > 5 && mean_residual > 40.0 {
            score += 50.0;
        }
    }

    // 5. Final adjustment based on fitting capability
    // If this is the only bin that fits, we are forced to take it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the "New Bin" choice heavily unless the bin is very empty or we are early in the stream.
    // If bin_residual == bin_capacity, this is the "New Bin" candidate.
    let is_new_bin = bin_residual == bin_capacity;

    // We want to minimize wasted space (post_residual), but we also want to avoid 
    // creating small gaps that are difficult to fill later. 
    // We penalize 'post_residual' values that are smaller than the smallest possible item (10).
    let fragmentation_penalty = if post < 10.0 && post > 0.0 {
        (10.0 - post) * 5.0
    } else {
        0.0
    };

    // Incorporate lookahead: if the next item fits into the current post_residual, 
    // reward this bin selection.
    let lookahead_reward = if next_item_size > 0 && (post_residual >= next_item_size) {
        -15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Base score is the residual space. We want to pack tightly (Best Fit).
    let mut score = post + fragmentation_penalty + lookahead_reward;

    // Adjust for the new bin candidate:
    // If it's a new bin, we add a penalty that decreases as the stream progresses,
    // reflecting that we are more willing to open bins late in the game to avoid 
    // bad fits in existing bins.
    if is_new_bin {
        // Base cost of opening a new bin is 50.0 (roughly half capacity).
        // We reduce this cost as we approach the end of the stream (progress -> 1.0).
        score += 50.0 * (1.0 - progress).powf(0.5);
    } else {
        // If we have very few fitting bins, prioritize using an existing bin to avoid 
        // unnecessary new bin creation.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Stabilize by penalizing high deviation from the mean residual of open bins
    // to encourage uniform bin filling.
    let mean_diff = (post - mean_residual).abs();
    score += mean_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

