        // 4. Fitting Pressure: If this is the only bin that fits the item, 
        // prioritize it to avoid forcing a new bin.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // 5. Progression Scaling: As we approach the end of the stream, 
    // prioritize filling existing bins more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
