    }

    // 5. Progress Normalization: As we reach the end of the stream, prioritize 
    // clearing out open bins (lower residuals are better).
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (post_residual as f64 * 0.1);

