pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but prioritize tight fits (0-5 range)
    // We heavily penalize large gaps that are unlikely to fit future items.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.5);
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. Fragmentation Avoidance: If we are creating a "dead zone" (e.g., residual < 10),
    // penalize this bin as it cannot accommodate the minimum item size effectively.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. Harmonic Scaling: Penalize based on how many bins are currently open,
    // encouraging consolidation as the stream progresses.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * (1.0 + progress * 5.0);

    // 5. Threshold Logic: If this is the only bin that fits, prioritize it heavily
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 6. New Bin Threshold: If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // Only do this if the average residual of existing bins is already very low (high utilization).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 40.0; // Discourage new bin if current utilization is poor
        } else {
            score += 60.0; // Default cost to open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit any likely subsequent items.
    // If post_residual is in the range (0, 10), it is highly likely to be wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (10.0 - post_residual as f64);
    }

    // 2. Lookahead Coupling: If next_item_size is known, penalize bin choice if it prevents
    // the next item from fitting in this bin, specifically if the current bin is the only one
    // that could potentially fit the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Open Bins Pressure: Penalize opening a new bin (bin_residual == bin_capacity)
    // based on how many bins are already open to prevent fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
        // If there are other bins that could fit the item, strongly discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Density Balancing: Favor bins that stay close to the mean residual to maintain
    // uniform bin utilization.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.5;

    // 5. Progression Scaling: As we approach the end of the stream, prioritize closing
    // existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Penalize large post_residuals (wasted space)
    // 2. Lookahead: If next_item_size fits in the post_residual, reward this bin heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 150.0;
        // Further refine: reward bins that leave minimal space after the next item
        score -= (post_residual - next_item_size) as f64 * 0.5;
    }

    // 3. Penalty for fragmentation: If the post_residual is small but > 0, 
    // it creates "dead space" that is hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 4. Strategic new bin opening: Only open a new bin if the current fit 
    // is truly terrible (e.g., post_residual is large) or if we are nearing the end.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 65.0;
        // If many bins are already open, discourage opening more unless necessary
        score += open_bins_count as f64 * 2.0;
    }

    // 5. Contextual adjustment: If this is the only bin that fits the current item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // 6. Mean residual balancing: Prefer bins that stay close to the system average
    // to keep the bin distribution uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // We favor bins where post_residual is near 0.
    score += post_residual as f64 * 1.5;

    // 2. Lookahead optimization: If next_item_size fits in the post_residual,
    // reduce the score (rewarding this bin for being a good host for the future item).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily 
    // unless the open bins are crowded or the current item is very large.
    if bin_residual == bin_capacity {
        // Only consider a new bin if we have few fitting options or the current item is large
        if fitting_bins_count > 0 {
            score += 45.0 + (item_size as f64 * 0.5);
        } else {
            score -= 10.0;
        }
    }

    // 4. Global State Awareness:
    // Avoid creating many bins early if mean_residual is high. 
    // If mean_residual is low, we are packing tightly; maintain that momentum.
    if mean_residual < 20.0 {
        score += (20.0 - mean_residual) * 0.5;
    }

    // 5. Dynamic Time Horizon:
    // As the stream nears completion, become more aggressive about filling
    // remaining bins rather than opening new ones.
    if progress > 0.9 {
        if bin_residual == bin_capacity {
            score += 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize creating tiny, unusable gaps (dead space)
    // The penalty is stronger when the gap is between 1 and 8 (too small for most items)
    let dead_space_penalty = if post_residual > 0 && post_residual < 10 {
        25.0 * (1.0 - (post_residual as f64 / 10.0))
    } else {
        0.0
    };

    // Factor in the lookahead: if next_item_size fits in the post_residual, reward this bin
    let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size {
        -15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Favor bins that align with the global mean residual to keep packing density uniform
    let uniformity_score = (post - mean_residual).abs() * 0.5;

    // Discourage opening new bins unless necessary (fitting_bins_count == 0)
    // As the stream progresses, become increasingly conservative about opening new bins
    let new_bin_penalty = if bin_residual == bin_capacity {
        50.0 + (progress * 50.0)
    } else {
        0.0
    };

    // Final score: minimize post_residual (Best Fit) with non-linear penalties/bonuses
    // We want the smallest post_residual (the tightest fit)
    let base_score = post.powf(1.2); 

    base_score + dead_space_penalty + lookahead_bonus + uniformity_score + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving a 'sliver' (unusable space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: if next_item_size is large, prefer bins that can accommodate it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // Reward bins that can fit the next item
        } else {
            score += 15.0; // Penalize bins that will force a new bin for the next item
        }
    }

    // Harmonic class logic: prioritize fitting items into bins that result in 
    // post_residuals that are multiples of common item sizes (e.g., 20, 25, 33)
    let harmonic_penalty = (post_residual % 20) as f64 + (post_residual % 25) as f64;
    score += harmonic_penalty * 0.5;

    // If this is the only fitting bin, prioritize it strongly to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Discourage opening a new bin unless the current residual is very poor
    if bin_residual == bin_capacity {
        // Only open new if we have many bins already or if the average residual is high
        score += (open_bins_count as f64 * 2.0) + (mean_residual * 0.5);
    }

    // Progression awareness: become more conservative as we approach the end of the stream
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit common items
    // (1..10 range is essentially dead space given min item size is likely > 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bins Pressure: Penalize opening new bins when existing capacity is sufficient.
    // We heavily penalize the "New Bin" candidate if fitting_bins_count > 0.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 40.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Compactness Reward: Favor bins that stay near the mean residual of the system
    // to keep the bin distribution uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // 5. Efficiency Scaling: As we near the end of the stream, prioritize closing bins
    // by preferring smaller post_residuals (Best Fit logic).
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals (wasted space)
    // 2. Lookahead matching: reward bins where the post_residual matches the next item size
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5;
    }

    // 3. Penalty for opening new bins: Only open if post_residual is very high (poor fit)
    // or if the current bin is the only one left and it creates a bad residual.
    if bin_residual == bin_capacity {
        // Penalty for creating a new bin: base cost + mean_residual factor
        score += 45.0 + (mean_residual * 0.2);
    } else {
        // Reward fitting into existing bins that are 'tight'
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Criticality: If this is the last chance for the current item, prioritize fitting
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Progression awareness: As we near the end of the stream, be more conservative
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize score.
    // Base: Post-residual (Best Fit logic).
    let mut score = post_residual as f64;

    // 1. Penalize creating "fragmented" bins (e.g., leaving space < 10, since min item size is 10).
    // If post_residual is small but > 0, it is likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead: If next_item_size is large, favor bins that can accommodate it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Global state: If we are late in the stream, be more conservative with opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin increases as we progress through the stream.
        score += 15.0 + (progress * 40.0);

        // If we have many open bins, penalize opening another one.
        score += open_bins_count as f64 * 2.0;
    }

    // 4. Fitting constraint: If this is the last bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Balance: If the current bin's residual is significantly better than the mean, 
    // it's likely a "good" bin; keep it healthy.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: punish larger post_residual (Best Fit principle)
    // We want to minimize post_residual (leaving as little space as possible)
    let mut score = post;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it often cannot fit future items. We punish values in (0, 10) heavily.
    if post > 0.0 && post < 10.0 {
        score += 50.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is less than next_item_size, we penalize the bin because it 
    // won't be able to take the next item, forcing a new bin later.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 25.0 * (1.0 - (post / next_item_size as f64));
        }
    }

    // Dynamic adaptation: As we approach the end of the stream, 
    // we become more aggressive about filling existing bins to reduce total count.
    // We penalize opening new bins (bin_residual == bin_capacity) more heavily as progress increases.
    if bin_residual == bin_capacity {
        score += 40.0 + (30.0 * progress);
    }

    // Global state awareness: If we have many open bins, penalize opening a new one 
    // or picking a bin that keeps the mean_residual high.
    if open_bins_count > 0 {
        score += (mean_residual / bin_capacity as f64) * 10.0;
    }

    // Fitting constraint: If this is the only bin that fits, give it a significant discount
    // to prevent unnecessary overflow into a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post-residuals to favor tight packing.
    // However, avoid "dead space" that is too small for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // Penalty for creating slivers that are hard to fill.
    }

    // 2. Harmonic Lookahead: If next_item_size fits in the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Last-Chance Logic: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 4. New Bin Thresholding: If evaluating a fresh bin (bin_residual == bin_capacity),
    // only choose it if the current state of open bins is highly fragmented.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Only open a new bin if the average space in existing bins is very poor
            // or if the current item is very large (e.g., > 70).
            score = 60.0 + (mean_residual * 0.5);
            if item_size > 75 {
                score -= 20.0;
            }
        }
    }

    // 5. Progression Scaling: As the stream nears completion, become more aggressive 
    // about packing into existing bins to minimize the final bin count.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Heavily penalize small, unusable gaps.
    // Gaps < 10 are effectively dead space since min item size is likely small,
    // but if we assume 10 is a lower bound, gaps < 10 are fatal.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual, 
    // prioritize this bin to maximize packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Penalize opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), add a high base cost.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 0.5);
    }

    // 4. Fitting Constraint: If this is the last bin that can fit the item, 
    // reward placing it here to avoid opening a fresh bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Global Efficiency: If the current post_residual is significantly 
    // lower than the mean_residual of other bins, it's a tight, efficient fit.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 6. Progress Scaling: As we approach the end of the stream, 
