}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating a new bin: only do this if forced or if no other good options exist.
    if bin_residual == bin_capacity {
        score += 25.0; 
    }

    // 2. Lookahead optimization: If the next item fits into the post_residual, 
    // prioritize this bin to maximize bin density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Further favor bins that result in a near-perfect fit for the next item.
        if (post_residual - next_item_size) < 10 {
            score -= 10.0;
        }
    }

    // 3. Avoid leaving "sliver" residuals that are too small to be useful for common items (mean_residual context).
    // If post_residual is positive but smaller than the mean_residual, it is likely "dead space".
    if post_residual > 0 && (post_residual as f64) < mean_residual {
        score += 5.0;
    }

    // 4. Pressure management: If this is the only bin that can fit the current item, 
    // it is a "forced" placement, so we prioritize it heavily to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Global progress normalization: As the stream progresses, become more conservative 
    // with empty space to minimize the final trailing bin count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best Fit Decreasing logic: Favor bins that result in small post_residual (tight packing)
    // We already have post_residual in score.

    // 2. Lookahead Penalty/Reward:
    // If the next item is large, avoid leaving a residual that is slightly too small for it.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // Penalize creating "fragmented" space that can't fit the next item
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else if post_residual >= next_item_size {
            // Reward creating space that fits the next item perfectly
            score -= (next_item_size as f64) * 0.5;
        }
    }

    // 3. Global State Balancing:
    // Prevent opening new bins unless necessary (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing bin could fit the item
            score += 150.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If no other choice, make it a neutral/base cost
            score += 50.0;
        }
    }

    // 4. Dynamic Time Horizon:
    // As we near the end of the stream, prioritize aggressive packing over future-proofing
    if progress > 0.8 {
        // Tighten the scoring to favor small post_residual even more
        score -= (bin_capacity - post_residual) as f64 * 0.2;
    }

    // 5. Residual Variance Control:
    // Discourage creating bins that deviate significantly from the mean residual
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 6. Last-Chance Mitigation:
    // If this is the only bin that can fit the item, prioritize it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

