    let mut score = post_res;

    // Penalty for creating a bin that is almost empty, especially early in the stream
    // post_res^2 helps differentiate between "good fit" (small post_res) and "wasteful fit" (large post_res)
    let waste_penalty = (post_res * post_res) / bin_capacity as f64;
    score += waste_penalty * (1.0 + progress);

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // that scales with the number of open bins and the mean residual space.
    // We only want to open a new bin if the existing options are truly poor.
    if bin_residual == bin_capacity {
