        score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;
    }

    // Lookahead logic: If the next item is large, penalize leaving a small gap now
    // that won't be usable later.
    if next_item_size > 0 {
        let gap_waste = if post_res < next_item_size as f64 && post_res > 0.0 {
            (next_item_size as f64 - post_res) * 0.5
        } else {
            0.0
        };
        score += gap_waste;
    }

    // If this is the only bin that can fit the item, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
