    // 5. Mean Residual Balancing: Prefer bins that are closer to the current average 
    // to keep bin utilization uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 6. Harmonic Modulo Constraint: Favor residuals that are multiples of 10 or 20,
