    // Encourage filling existing bins that are close to the mean residual to keep distribution uniform.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.1;

    // Last chance heuristic: if this is the only bin that fits the current item, 
    // prioritize it heavily to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && !is_new_bin {
