    // 3. Open Bins Pressure: If this is a new bin (bin_residual == bin_capacity), 
    // only choose it if the current fitting options are extremely poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one can fit the item.
            score += 60.0 + (open_bins_count as f64 * 5.0);
        }
    } else {
        // 4. Best-Fit Bias: Encourage filling bins that are already partially full.
        // We favor bins where the current placement brings the residual closer to the mean.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;

        // If this is the last chance to fit the item in an open bin, reward it to avoid opening a new one.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // 5. Progression Scaling: As we near the end of the stream, prioritize packing density over fragmentation concerns.
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + (progress * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

