    // 4. Global balance: If the current bin's post_residual is significantly worse than
    // the mean residual of open bins, penalize it to prevent fragmentation.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.8;
