    // Lower post_residual is better, but we penalize bins that become "too tight" 
    // too early in the stream, which prevents future-proofing.
    let mut score = post * (1.0 + 0.5 * (1.0 - progress));

    // Penalty for creating a bin that is almost empty (fragmentation)
    // Only apply if we are not opening a brand new bin (bin_residual != bin_capacity)
    if bin_residual != bin_capacity {
        // High penalty for creating small residues that are hard to fill (e.g., 1-9)
        if post_residual > 0 && post_residual < 10 {
            score += 40.0 * (1.0 - progress);
        }

        // Lookahead integration: 
        // If the next item fits into the current post_residual, prioritize this bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0 * (1.0 - 0.2 * progress);
