        // Only open a new bin if the mean_residual is already very low,
        // or if fitting_bins_count is zero (forced).
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if existing bins are available
            score += 60.0 + (40.0 * progress);
        } else {
            // Base cost for opening a new bin when necessary
            score = 50.0;
