            score += 120.0 + (open_bins_count as f64 * 2.0);
        } else {
            // Necessary new bin: normalize score to be competitive.
            score = 40.0; 
        }
    }

    // 3. Lookahead heuristic: If the next item is large, favor bins that leave 
    // enough space for it (or pack tight if no space is left).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item.
            score -= 15.0;
        } else if post_residual < 20 && post_residual > 0 {
            // Penalize bins that are left with a small, unusable sliver before a large item.
            score += 25.0;
        }
    }

    // 4. Global pressure: Encourage using bins that are already closer to the mean_residual
    // to keep the bin fill-levels balanced (homogeneity).
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize leaving small, unusable gaps.
    // If post_residual is very small (< 10), it's often a "dead space" trap.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the remaining space, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= (30.0 / (1.0 + diff)); 
    }

    // 3. Mean Residual Balancing: Avoid bins that deviate significantly from the average state.
    // This helps keep filling density uniform across all active bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 4. Scarcity Logic: If this is the last bin that can fit the item, prioritize it 
    // to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. New Bin Thresholding: Make opening a new bin expensive unless the fit is truly optimal.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin; only choose if current options are very poor.
        score += 35.0;

        // If we are near the end of the stream, penalize new bins even more.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
