    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // 1. Base cost: The tighter the fit, the better (Best Fit).
    // post_residual is the space remaining. Minimizing this is the standard goal.
    let mut score = post_residual as f64;

    // 2. Penalty for opening a new bin prematurely.
    // If we have options, avoid new bins unless the current fit is terrible.
    if is_new_bin {
        if fitting_bins_count > 0 {
