            // Penalize proportional to the wasted space that could have been used by the next item.
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        } else {
            // This placement preserves space for the next item. Reward it.
            score -= (next_item_size as f64 * 0.2);
        }
    }

    // 4. Dynamic scaling based on progression.
    // Near the end of the stream, prioritize packing density over future flexibility.
    if progress > 0.8 {
        score -= (open_bins_count as f64 * 0.1);
    }

    // 5. Fragility Penalty: Avoid creating "sliver" residuals (e.g., 1-5 units left) 
    // which are statistically hard to fill later.
    if post_residual > 0 && post_residual < 8 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize small residuals (fragmentation) non-linearly.
    // If post_residual is very small (e.g., 1-5), it creates unusable space.
    let fragmentation_penalty = if post_res > 0.0 && post_res < 10.0 {
        (10.0 - post_res).powi(2) * 2.0
    } else {
        0.0
    };

    // Reward bins that leave space for the next item if lookahead is available.
    let lookahead_reward = if next_item_size > 0 && post_res >= next_item_size as f64 {
        -15.0 * (1.0 - progress)
    } else if next_item_size > 0 && post_res < next_item_size as f64 {
        10.0
    } else {
        0.0
    };

    // Encourage filling bins deeper as the stream nears the end.
    let completion_pressure = (1.0 - progress) * (bin_capacity as f64 - post_res);

    // If this is a new bin, penalize it unless it's necessary.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        if fitting_bins_count == 0 {
            -20.0 // Necessary to open
        } else {
            // Discourage opening new bins early unless the fit is terrible in others.
            50.0 + (progress * 30.0)
        }
    } else {
        0.0
    };

    // Base score: prioritize smaller post_residuals (Best Fit logic)
    // but modulate with the non-linear penalties/rewards.
    let score = post_res 
        + fragmentation_penalty 
        + lookahead_reward 
        - (completion_pressure * 0.1) 
        + new_bin_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
