    // 2. Lookahead logic: if next_item_size is large, favor bins that can still accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that can fit the next item
        } else if post_residual > 0 && post_residual < 15 {
            score += 20.0; // Penalize creating "sliver" space that is hard to fill
        }
    }

    // 3. Global state balance: avoid creating too many open bins if the mean residual is already high.
    // If mean_residual is high, we want to pack into existing bins to consolidate.
    if !is_new_bin {
        score += (mean_residual * 0.2);
    }

    // 4. Final adjustment: If this is the only bin that fits, prioritize it heavily to avoid new bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Best-Fit (minimize post_residual)
    let mut score = post;

    // Penalty for creating a bin with very small residual (the "fragmentation trap")
    // If post_residual is small but > 0, it's often worse than 0.
    if post > 0.0 && post < 15.0 {
        score += 25.0 * (1.0 - (post / 15.0));
    }

    // Lookahead: If the next item is large, favor bins that have space for it.
    // We penalize bins that cannot fit the next item if the current item leaves a "useless" gap.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding: as we near the end of the stream, prioritize closing bins
    // by being more aggressive with Best-Fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Penalize opening a new bin heavily, but scale it down as the stream progresses
    // to allow for better packing density at the very end.
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - (progress * 0.5));
    }

    // Incorporate mean_residual to balance load across open bins
    // If this bin is significantly emptier than the average, it's a good place to pack.
    if bin_residual as f64 > mean_residual {
        score -= 5.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating small, unusable gaps (The "Dead Space" avoidance)
    // If post_residual is small but > 0, it's often a bad fit unless it perfectly matches future items.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Harmonic Lookahead: reward fitting the item such that the post_residual
    // is a multiple of the next_item_size, effectively preparing for the next step.
    if next_item_size > 0 {
        let remainder = post_residual % next_item_size;
        // If the post_residual can perfectly accommodate the next item, heavily reward it.
        if remainder == 0 {
            score -= 30.0;
        } else {
            // Penalize based on how much space is wasted relative to the next item
            score += (remainder as f64) * 0.5;
        }
    }

    // 3. Pressure Management:
    // If we have many open bins, we want to consolidate (prefer smaller residuals).
    // If we have few open bins, we can be more flexible.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score += (open_bins_count as f64) * fill_ratio * 5.0;

    // 4. Threshold for opening new bins:
    // If the bin is new (bin_residual == bin_capacity), set a baseline cost to open a new bin.
    // This cost is modulated by how many bins are already open to prevent fragmentation.
    if bin_residual == bin_capacity {
        score = 25.0 + (open_bins_count as f64 * 0.5);
    }

    // 5. Fitting constraints:
    // If this is the last bin that can fit the item, prioritize it to avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Global progress adjustment:
    // As the stream progresses, prioritize tightest fits (Best-Fit behavior).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    score
}

