    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large residual space left over (standard Best-Fit logic)
    // We already have post_residual in the score, which encourages minimizing the gap.

    // 2. Lookahead Synergy: Reward placements that leave exactly enough space for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // Strong reward for perfect 2-step fit
        } else if post_residual > next_item_size {
            // Reward if the current placement leaves a gap that can accommodate the next item
            score -= 15.0;
        } else {
            // Penalize if the next item will definitely force a new bin
            score += 10.0;
        }
    }

    // 3. Mean Residual Balancing: Avoid bins that deviate significantly from the average occupancy.
    // This helps maintain a uniform "tightness" across all open bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 4. Last-Chance Mitigation: If this is the only bin that fits the item, 
    // it is inherently valuable. We lower the score to make it more attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 5. New Bin Penalty: If this is a new bin (bin_residual == bin_capacity), 
    // heavily penalize it unless no other bin can fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0; // Strong deterrent against opening new bins prematurely
        }
    }

    // 6. Progressive Tightening: As the stream nears completion, become more aggressive 
    // about filling bins to reduce leftover capacity.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
