pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual if it's too small to accommodate 
    // common small items (e.g., < 10) or too small to fit the lookahead item.
    // If post_residual is in the "danger zone" (1..9), it's likely wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item can fit in the post_residual, 
    // reward this bin choice heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Fragmentation Penalty: If this is the only fitting bin, prioritize it 
    // to avoid opening a new bin unnecessarily (Best Fit behavior).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 4. Global Pressure: As the stream progresses, penalize opening new bins 
    // (where bin_residual == bin_capacity) to encourage packing density.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += (open_bins_count as f64) * 5.0 * (1.0 + progress);
    }

    // 5. Mean Residual Alignment: Penalize bins that deviate significantly 
    // from the average fullness, promoting uniform bin usage.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, penalize it based on how many existing bins could have taken the item.
    // We want to force usage of existing bins unless they are extremely poor fits.
    if bin_residual == bin_capacity {
        score += (fitting_bins_count as f64) * 25.0;
        // Penalize opening a new bin if we are early in the stream
        score += (1.0 - (step_index as f64 / total_items as f64)) * 10.0;
    } else {
        // 2. Lookahead optimization: If post_residual is a perfect match for the next item, reward it.
        if next_item_size > 0 && (post_residual as i32 - next_item_size as i32).abs() < 5 {
            score -= 15.0;
        }

        // 3. Penalty for leaving "dead" space (too small to fit typical items).
        // If the remaining space is small but not zero, it's often worse than a slightly larger space.
        if post_residual > 0 && post_residual < 10 {
            score += 20.0;
        }

        // 4. Balance current bin utilization against the global average.
        // If this bin's post_residual is significantly lower than the global mean, it's a tight fit.
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }

        // 5. If this is the last chance to fit the item into an existing bin, prioritize it strongly
        // to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // post_residual: 0 is perfect, high is bad.
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (gaps < 10, as items are >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead logic: if we can fit the next item, prioritize bins that keep a "good" residual for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that fit the next item perfectly (residual 0 after next item)
            let secondary_residual = post_residual - next_item_size;
            score -= (100.0 - secondary_residual as f64) * 0.5;
        } else {
            // Penalize bins that cannot fit the next item if we are running out of bins
            score += 20.0;
        }
    }

    // 3. Global state: balance load across open bins.
    // If this bin's residual is much higher than the mean, we are creating an imbalance.
    if (bin_residual as f64) > mean_residual {
        score += 10.0;
    }

    // 4. New bin management:
    // Only open a new bin if the current fit is terrible (post_residual > 40)
    // or if we have no other choice.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 && post_residual < 40 {
            score += 100.0; // Heavily penalize opening a new bin if a decent fit exists
        } else {
            score -= 10.0; // Otherwise, prefer opening a new bin to save space for larger future items
        }
    }

    // 5. Time horizon: as we approach the end of the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: punish larger remaining space (Best Fit principle)
    // We want to minimize post_residual, so it stays as the base.
    let mut score = post;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // If the post_residual is < 10, it's often a waste.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Lookahead influence: If the next item is large, favor bins that have more space left.
    // If next_item_size > post_residual, this bin will likely be unable to take the next item.
    if next_item_size > 0 {
        if (next_item_size as f64) > post {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding: As the stream progresses, become more aggressive at filling 
    // current bins to avoid opening new ones. 
    // If fitting_bins_count is low, prioritize filling this bin more heavily.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress);
    }

    // Heuristic for new bin:
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    // Penalize opening new bins increasingly as we approach the end of the stream.
    if bin_residual == bin_capacity {
        score += 25.0 + (progress * 50.0);
    }

    // Interaction with mean_residual:
    // If the current bin's post-fit residual is significantly lower than the global mean,
    // it is a very efficient placement.
    if post < mean_residual {
        score -= (mean_residual - post) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: penalize large post_residuals (wasted space)
    // 2. Harmonic Class Penalty: penalize post_residuals that are small but unusable 
    //    for common item sizes (e.g., < 10), unless the bin becomes perfectly full (0).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 10.0; // Reward perfect fits
    }

    // 3. Lookahead Logic: If the next item can fit in the current post_residual, 
    //    heavily favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Scarcity/Congestion weighting: If we have many open bins, penalize opening a new one.
    //    If fitting_bins_count is 1, this is the last chance to place the item without
    //    opening a new bin, so we reward placing it here.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Heavily penalize opening a new bin unless we have very few open bins
            score += 60.0 + (open_bins_count as f64 * 5.0);
        }
    } else if fitting_bins_count == 1 {
        // Last chance to fit in an existing bin
        score -= 30.0;
    }

    // 5. Normalization against mean_residual to prevent fragmentation
    //    If this bin's post_residual is significantly better than the mean, favor it.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 6. Progressive tightening: As the stream nears the end, prioritize closing bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
