pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize bins that leave tiny, unusable fragments (1-9)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Matching: Reward bins that fit the next item perfectly (Best-Fit-Lookahead)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            score -= 10.0;
        } else {
            score += 20.0;
        }
    }

    // 3. Last Chance Logic: Penalize opening a new bin if we have fitting options
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one can accommodate the item
            score += 60.0 + (fitting_bins_count as f64 * 5.0);
        } else {
            // Normalize new bin cost to prevent infinite growth
            score = 40.0;
        }
    }

    // 4. Global Consolidation: If bin is nearly full, prioritize it to minimize open bin count
    if post_residual < 15 {
        score -= 25.0;
    }

    // 5. Mean Residual Balancing: Avoid bins that deviate significantly from the mean
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 6. Progress Scaling: As we reach the end of the stream, tighten constraints
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Penalize creating "dead space" (small residuals that cannot fit common items)
    // Residuals < 10 are often useless given the item range.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 + (5.0 * (1.0 - progress));
    }

    // 2. Lookahead optimization: If next_item_size fits in the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // 3. Pressure management: If we are near the end of the stream, prioritize filling existing bins.
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // 4. Heuristic for opening a new bin:
    // Only open a new bin if the current best fit is "too tight" or poor, 
    // but penalize it heavily early in the stream.
    if is_new_bin {
        if fitting_bins_count == 0 {
            score = 0.0; // Forced to open
        } else {
            // Opening a new bin is expensive. Only do it if existing fits are extremely poor.
            // A score of 50.0 is the baseline threshold to trigger a new bin over a "bad" fit.
            score = 50.0 + (25.0 * progress);
        }
    } else {
        // Favor bins that are already partially filled to keep the open_bins_count low.
        score += (open_bins_count as f64) * 2.0;

        // Reward bins that are becoming "full" (Best Fit Decreasing logic)
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // The base strategy is Best-Fit Decreasing logic (minimizing post_residual).
    // We penalize bins that leave very small, unusable gaps (1-9) which are hard to fill.
    let gap_penalty = if post_residual > 0 && post_residual < 10 {
        25.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Use lookahead: if the next item is large, prioritize keeping the residual high.
    // If next_item_size is 0 (end of stream), we prioritize packing tightest.
    let lookahead_factor = if next_item_size > 0 {
        if post_residual < next_item_size {
            30.0 * (1.0 - progress)
        } else {
            -10.0 * (1.0 - progress)
        }
    } else {
        0.0
    };

    // Balance against the number of open bins to prevent unnecessary fragmentation.
    // As the stream progresses, prioritize closing bins (lower open_bins_count).
    let efficiency_pressure = (open_bins_count as f64) * 2.0 * progress;

    // New bin candidate logic:
    // If the bin is new, it has a high residual. We only choose it if the current
    // fitting options are extremely poor (i.e., would result in high gap_penalty).
    let mut score = post + gap_penalty + lookahead_factor + efficiency_pressure;

    if bin_residual == bin_capacity {
        // Strongly discourage opening a new bin unless the existing fitting bins
        // are all highly inefficient (high post_residual).
        score = 45.0 + (mean_residual * 0.5);

        // If no other bins can fit the item, opening a new bin is mandatory.
        if fitting_bins_count == 0 {
            score = -100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
