pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (residuals too small for common items, but too large to be efficient)
    // If post_residual is between 1 and 9, it is extremely unlikely to fit another item.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Aggressive 2-step lookahead: 
    // Reward bins where the post_residual can perfectly or nearly accommodate the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - diff) * 0.5; // Strong reward for high-probability lookahead matches
        } else {
            // Penalize if we block the next item from fitting in this bin
