        }
    }

    // 3. Balance usage: avoid opening new bins if existing bins are viable.
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless fitting_bins_count is low.
    if bin_residual == bin_capacity {
        score += 45.0; 
        // If we are forced to open a new bin, make it expensive unless it's the only option.
        score += (open_bins_count as f64) * 2.0;
    }

    // 4. Global state awareness:
    // If the bin's residual is significantly better than the global mean, prioritize it.
    let residual_advantage = mean_residual - (post_residual as f64);
    score -= residual_advantage * 0.3;

    // 5. Urgency:
    // If it is the last chance for this item (fitting_bins_count == 1), lower the barrier.
    if fitting_bins_count == 1 {
