pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the post_residual (Best Fit strategy).
    // We penalize high post_residual to favor tightly packed bins.
    let mut score = post_res;

    // Penalty for creating a new bin:
    // If bin_residual == bin_capacity, this is a new bin candidate.
    // We scale this penalty by the progress; as the stream nears the end, 
    // it becomes more expensive to open new bins.
    if bin_residual == bin_capacity {
        score += (bin_capacity as f64) * (1.0 + progress);
    }

    // Lookahead interaction:
    // If next_item_size is large, we want to preserve space (low post_residual).
    // If next_item_size is small, we are less sensitive to tight space.
    if next_item_size > 0 {
        let fit_next = (post_res >= next_item_size as f64) as i32 as f64;
        score -= fit_next * (next_item_size as f64) * (1.0 - progress);
    }

    // Non-linear coupling with mean_residual:
    // If the current bin's post_residual is much worse than the global average, 
    // we penalize it to force better distribution across open bins.
    let residual_diff = post_res - mean_residual;
    if residual_diff > 0.0 {
        score += residual_diff.powf(1.5) * (1.0 - progress);
    }

    // Fitting bins constraint:
    // If this is the only bin that can fit the item, we lower the score 
    // to prioritize utilizing existing capacity over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= (bin_capacity as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #1301: Harmonic-Residual Balancing
    // We prioritize bins that result in "tight" residuals (Best Fit) 
    // but penalize residuals that are too small to fit common upcoming items.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize residuals that are small but unusable.
    // If a bin has a small residual, it becomes "dead" space unless it fits the next item.
    if !is_new_bin {
        if next_item_size > 0 && post_residual < next_item_size {
