        if post_residual < 10 {
            score += 25.0;
        }

        // 3. Efficiency scaling: Favor bins that are already "half-full" or more
        // to consolidate space usage (Best Fit logic).
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    } else {
        // 4. New Bin Threshold: Only open a new bin if fitting_bins_count is low
        // or the current mean_residual is extremely poor (fragmentation).
        if fitting_bins_count > 0 {
