        }

        // If we are late in the stream, be more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 10.0;
    }

    // 5. Lookahead smoothing: If post_residual is a multiple of a likely item size,
    // it's a "harmonic" fit.
    if next_item_size > 0 && post_residual % next_item_size == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small to fit typical future items (e.g., < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If the next item can fit in the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary, 
    // or if the current bin is a "bad fit" (high post_residual).
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if other bins exist
        score += (open_bins_count as f64) * 15.0;
    } else {
