    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 35.0;
        }
        // If it's the very beginning or end, soften the penalty.
        let progress = step_index as f64 / total_items as f64;
        if progress < 0.05 || progress > 0.95 {
            score -= 10.0;
        }
    }

    // 5. Mean-Residual coupling: If the current bin is significantly worse 
    // than the average open bin, penalize it.
    if (post_residual as f64) > mean_residual + 10.0 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
