    // 5. Global Load Balancing:
    // Favor bins that keep the mean residual of all bins consistent.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // 6. Tightness Bonus:
    // If this is the last chance to use a bin for this item, prioritize it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    score
