pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize new bin creation (bin_residual == capacity) as progress increases
    // to force consolidation in later stages of the stream.
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_bin_penalty = is_new_bin * (50.0 + (progress * 100.0));

    // Best-Fit Decreasing logic: minimize post_residual (the space left)
    // but apply a non-linear penalty for creating "dead space" (small post_residual < 10)
    // which is usually harder to fill later.
    let dead_space_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post).powf(2.0) * 5.0
    } else {
        0.0
    };

    // Lookahead coupling: if the next item is large, prefer bins that have enough space
    // to accommodate both the current and the next item (post_residual >= next_item_size).
    let lookahead_benefit = if next_item_size > 0 && post >= next_item_size as f64 {
        -25.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Factor in the mean_residual to favor bins that are already "tighter"
    // relative to the average, helping to keep the bin distribution uniform.
    let tightness_factor = (post - mean_residual) * 0.5;

    // Final score: lower is better. 
    // We want small post_residual, but heavily weighted against small slivers of dead space
    // and biased by the lookahead and stream progress.
    post + new_bin_penalty + dead_space_penalty + lookahead_benefit + tightness_factor
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
