pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_res;

    // Penalty for creating a "sliver" (fragmentation)
    // Small residuals are hard to fill; penalize them non-linearly.
    // If post_res is small (e.g., < 15), it creates dead space.
    if post_res > 0.0 && post_res < 20.0 {
        score += (20.0 - post_res).powf(1.5);
    }

    // Lookahead influence: If the next item is large, prioritize keeping 
    // larger residuals open. If the current bin fits the next item, reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.5;
        } else {
            score += (next_item_size as f64 - post_res) * 0.2;
        }
    }

    // Dynamic thresholding based on stream progress:
    // As the stream progresses, we become more conservative about opening new bins.
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // increasingly as we approach the end of the stream.
    if bin_residual == bin_capacity {
        score += 25.0 + (progress * 50.0);

        // If we have other options, heavily discourage opening a new bin
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Balance the global state:
    // If the current bin's post_residual is significantly better than the mean,
    // reward it to encourage packing consistency.
    if post_res < mean_residual {
        score -= (mean_residual - post_res) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #1316: Harmonic-Residual Balancing
    // We prioritize bins that result in "harmonic" residuals (multiples of common divisors)
    // and penalize fragmented space that cannot accommodate the lookahead item.

    let mut score = post_residual as f64;

    // 1. Base penalty for creating a new bin:
    // If this is a new bin (residual == capacity), we apply a progressive tax based on 
    // how many bins are already open to discourage fragmentation.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64 * 0.5);
    }

    // 2. Harmonic Class Logic:
    // We favor post_residuals that are close to 0 (Best Fit) or close to 
    // common divisors of the capacity (e.g., 20, 25, 50).
    let harmonic_penalty = (post_residual % 25) as f64 * 0.4;
    score += harmonic_penalty;

    // 3. Lookahead Synergy:
    // If the next item cannot fit in the post_residual, we penalize the bin.
    // If it fits perfectly (post_residual == next_item_size), we reward it heavily.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 20.0;
        } else if post_residual == next_item_size {
            score -= 10.0;
        } else {
            // Reward bins that leave exactly enough room for the next item
            score += ((post_residual - next_item_size) as f64) * 0.1;
        }
    }

    // 4. Density Balancing:
    // If the bin is becoming very empty compared to the mean, it's a "bad" bin.
    if (bin_residual as f64) > mean_residual * 1.5 {
        score += 5.0;
    }

    // 5. Urgency factor:
    // If this is the only bin that can fit the item, prioritize it (lower score).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residual ranges that are 
    // too small to fit any future items (1..9), as items are >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins (bin_residual == capacity)
    // unless the fit is extremely tight (Best Fit behavior).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if other bins can accommodate the item.
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            // No other choice, normalize the cost.
            score -= 10.0;
        }
    }

    // 4. Global Consolidation: If we are deep into the stream, bias towards 
    // filling bins with lower residuals to reduce fragmentation.
    let progress = step_index as f64 / total_items as f64;
    if post_residual < 5 {
        score -= 15.0 * progress;
    }

    // 5. Mean residual alignment: Avoid bins that deviate significantly 
    // from the average residual to promote uniform bin usage.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Lower post_residual is generally better (tighter fit).
    // We treat the "New Bin" case (bin_residual == bin_capacity) as a baseline to be penalized.
    if bin_residual == bin_capacity {
        score += 45.0; 
    }

    // 2. Lookahead Synergy: If the post_residual can perfectly or nearly accommodate the next item, 
    // reward this placement heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let diff = (post_residual - next_item_size) as f64;
            score -= (25.0 / (1.0 + diff));
        } else {
            // Penalize creating a bin that is too small for the next item if it could have fit elsewhere
            score += 15.0;
        }
    }

    // 3. Fragmentation Control: Avoid leaving residuals that are useless (e.g., < 10) 
    // unless they fit the next item.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 4. Global Density Balance: If we have many open bins, penalize opening new ones 
    // and favor bins closer to the mean_residual to consolidate space.
    let residual_delta = (post_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.1;

    // 5. Urgency: If this is the only bin that fits the current item, prioritize it 
    // to avoid unnecessary bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Progress Scaling: As we near the end of the stream, prioritize tight fits 
    // to avoid stranding items in new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

