    // We heavily punish leaving space that is too small for common item sizes
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Lookahead Coupling: If next item fits in the current post_residual, prioritize this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // 3. Fragmentation Avoidance: If this is the last fitting bin, prioritize it to keep it open
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 4. Global State/Dynamic Threshold: As we approach the end of the stream, 
    // become more aggressive in packing to minimize new bin openings
    if progress > 0.8 {
        score -= (1.0 - progress) * 50.0;
    }

    // 5. Empty Bin Handling: Discourage opening new bins unless the current fit is catastrophic
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score = 40.0;

        // If we have many open bins, opening another is costly
        score += (open_bins_count as f64) * 2.5;

        // If the mean residual of current bins is high, we should try to use them instead
        score += mean_residual * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Progress factor: 0.0 at start, 1.0 at end
    let progress = step_index as f64 / total_items as f64;

    // Penalize small residuals (fragmentation) non-linearly.
    // As post_residual approaches 0, the penalty grows exponentially.
    // We favor larger post_residuals that leave space for future items.
    let frag_penalty = if post_residual > 0 {
        1.0 / (post_residual as f64 + 0.1)
    } else {
        100.0 // Severe penalty for near-perfect fits that might be "too tight"
    };

    // Lookahead logic: if next_item_size is large, favor larger post_residuals
    // to accommodate the upcoming item, weighted by how far we are in the stream.
    let lookahead_weight = if next_item_size > 0 {
        (next_item_size as f64 / bin_capacity as f64) * (1.0 - progress)
    } else {
        0.0
    };

    // Base score is the post_residual (Best Fit principle).
    // We subtract the lookahead expectation and add the fragmentation penalty.
    let mut score = (post_residual as f64) 
        + (frag_penalty * 10.0) 
        - (lookahead_weight * post_residual as f64 * 2.0);

    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // heavily early in the stream, but relax the penalty as the stream nears completion
    // to allow for better packing density in the final stages.
    if bin_residual == bin_capacity {
        score += (40.0 * (1.0 - progress)) + (open_bins_count as f64 * 0.5);
    } else {
        // If it's an existing bin, reward it if it's the only one that fits (fitting_bins_count == 1)
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Adjust for the global state: if current mean_residual is high, 
    // we are already being inefficient; penalize opening new bins further.
    score += (mean_residual * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize minimizing post_residual (the core of the score).
    // 2. Harmonic penalty for small residuals: avoid creating "unfillable" gaps (1-9).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 3. Lookahead integration: If the next item is large, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can fit the next item perfectly
            score -= (next_item_size as f64) * 0.8;
        } else {
            // Penalize bins that render the next item impossible to place here
            score += 15.0;
        }
    }

    // 4. Threshold adaptation: If this is the only bin that fits, heavily favor it to avoid new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. New Bin Strategy: Penalize opening a new bin unless the current residual is very inefficient.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already quite low, 
        // suggesting current bins are too crowded to be flexible.
        if mean_residual > 20.0 {
            score += 10.0;
        } else {
            score += 60.0;
        }
    }

    // 6. Progressive tightening: As the stream nears the end, be more aggressive with space packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

