    // If post_residual is in the range (0, 10), it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.5;
    }

    // 3. Open Bins Pressure: Penalize opening new bins when existing ones have capacity.
    // Discourage new bins if we have many open bins already, unless the fit is perfect.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
        if post_residual == 0 {
            score -= 5.0; // Reward perfect fit in new bin if it's the only option
        }
    }

    // 4. Fitting Density: If this is the only bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. Mean residual equilibrium: Favor bins that keep the overall mean residual consistent.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residuals that cannot fit common items)
    // If the post_residual is less than 10 (the minimum item size), it is essentially wasted space.
    if post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead matching: Reward placements where the remaining space fits the next item.
    // If post_residual is close to next_item_size, we create a high-probability fit for the next step.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact or near-exact fits for the next item
            score -= (100.0 - (post_residual as f64 - next_item_size as f64).abs());
        } else {
            // Penalize if the current placement makes the next item impossible to fit in this bin
            score += 20.0;
        }
    }

    // 3. Efficiency pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless there are no other options (fitting_bins_count == 0).
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 150.0;
    }

    // 4. Global state optimization: Keep open bin residuals aligned with the mean.
    // This promotes tighter packing across all bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // 5. Progress-based scaling: Become more aggressive as we near the end of the stream
    // to minimize the impact of "leftover" items.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
