    // The base score is post_residual, which inherently favors tighter fits.

    // 2. Lookahead Synergy: If the next item fits perfectly into the post_residual, prioritize this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that leave exactly enough space for the next item
            let slack = (post_residual - next_item_size) as f64;
            score -= (100.0 - slack) * 0.5;
        } else {
            // Penalize if this bin becomes unable to take the next item
            score += 20.0;
        }
    }

    // 3. Fragmentation Control: Penalize creating "unusable" small gaps (e.g., < 10)
    // unless it results in a perfect fit (post_residual == 0).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // 4. Global State Balancing: Avoid over-filling bins too early if we are early in the stream.
    // If we have many open bins, try to consolidate by favoring lower mean_residual.
    if open_bins_count > 1 {
        score += (mean_residual - post_residual as f64) * 0.2;
    }

    // 5. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on progress.
    // We want to avoid opening new bins late in the stream if possible.
    if bin_residual == bin_capacity {
        score += 45.0 + (progress * 25.0);
    }

    // 6. Scarcity Logic: If this is the only bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the post-residual space (Best Fit principle).
    // Penalize leaving very small, unusable gaps (1-5 range) heavily.
    let mut score = post_res;
    if post_res > 0.0 && post_res < 6.0 {
        score += 25.0 * (1.0 - (post_res / 6.0));
    }

    // Lookahead logic: if next item is large, favor bins that can accommodate it.
    // If next_item_size is 0, we are at the end, so maximize packing density.
    if next_item_size > 0 {
        let fit_margin = post_res - next_item_size as f64;
        if fit_margin >= 0.0 {
            // Reward bins that maintain room for the next item.
            score -= 15.0 * (1.0 - (fit_margin / bin_capacity as f64));
        } else {
            // Penalize bins that will definitely force a new bin for the next item.
            score += 10.0 * (1.0 - progress);
        }
    }

    // Dynamic pressure: As the stream progresses, become more conservative about opening new bins.
    // If fitting_bins_count is 1, this is the only bin that can take the item; prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Discourage opening a new bin (bin_residual == bin_capacity) unless the 
    // current fit is extremely poor (post_residual > 40).
    if bin_residual == bin_capacity {
        score += 40.0 + (progress * 20.0);
    }

    // Penalty for increasing the number of active bins relative to mean residual health.
    score += (open_bins_count as f64 * 0.5) * (1.0 - (mean_residual / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for opening a new bin
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    // 2. Harmonic Class Logic: Penalize residuals that cannot fit common item sizes (10, 20, 25, 33, 50)
    // We want to avoid creating "dead space" that is too small for future items.
    let residual_penalty = match post_residual {
        0..=9 => 30.0,      // Creating unusable slivers is bad
        10..=19 => 10.0,    // Good for small items
        20..=24 => 5.0,     // Good for 20s
        25..=32 => 2.0,     // Good for 25s
        _ => 0.0,
    };
    score += residual_penalty;

    // 3. Lookahead Logic: If the next item is large, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that can fit the next item
        } else if post_residual > 0 && post_residual < 20 {
            score += 20.0; // Penalty if this bin will likely be useless for the next item
        }
    }

    // 4. Pressure Logic: If we have many open bins, penalize opening another one heavily
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
    }

    // 5. Efficiency refinement: favor tighter fits (Best Fit principle)
    // We emphasize the post_residual but normalize by the capacity to keep variance bounded
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // 6. Progression scaling: as we approach the end of the stream, prioritize closing bins
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (post_residual as f64) * 0.5;
    }

