    let mut score = post_residual as f64;

    // 1. DEAD SPACE AVOIDANCE: Heavily penalize post_residual values that are too small to fit 
    // any likely future items (e.g., < 10), as these create "orphaned" space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. LOOKAHEAD COUPLING: If the next item cannot fit into the post_residual, 
    // penalize this bin to save it for a better match or prioritize tighter fits.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 15.0;
    }

    // 3. OPEN BINS PRESSURE: Discourage opening new bins (bin_residual == bin_capacity) 
    // unless the fit is extremely poor or we are near the end of the stream.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 4. FRAGMENTATION CONTROL: Penalize bins that deviate significantly from the mean 
    // residual of currently open bins to promote uniform bin usage.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. LAST CHANCE LOGIC: If this is the only bin that can fit the item, 
    // strongly reward picking it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
