        score += 35.0 + (open_bins_count as f64 * 0.5);
    }

    // 4. Fragmentation Control: If this bin is the only one that fits the item 
    // (fitting_bins_count == 1), prioritize it to avoid "locking" a bin 
    // that might be better used for a larger future item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // 5. Global Mean Adjustment: If the current bin's post_residual is significantly 
    // better than the mean of all open bins, reward the choice to keep the 
    // packing density high.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 6. Progressive Tightening: As the stream nears the end, become more 
    // aggressive about fitting items to minimize the final bin count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: We want the smallest post_residual (Best Fit principle).
    let mut score = post_residual as f64;

    // Penalty for creating a "fragment" (unusable space < 10, since min item size is 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // If this is a new bin, penalize it heavily unless we are forced to use it.
    // However, reward opening a new bin if the current mean_residual is very low (bins are packed tight).
    if is_new_bin {
        score += 40.0 - (mean_residual * 0.5);
    } else {
        // Reward filling bins that have little space left to avoid keeping many partially full bins.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Lookahead: If the next item can fit in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
