    }

    // If only one bin can fit the current item, prioritize it to avoid creating a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0;
    }

    // Dynamic horizon: As we approach the end of the stream, prioritize aggressive packing.
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
