    if post_residual > 0 && post_residual < 10 {
        score += 25.0; 
    }

    // 2. Harmonic Lookahead: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // 3. Pressure management: If many bins can fit this item, avoid creating a new one.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other options exist.
            score += 60.0 + (open_bins_count as f64 * 2.0);
        }
    } else {
        // 4. Harmonic balancing: Reward bins that stay close to the global mean residual.
        // This encourages uniform filling across the bin set.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;

        // 5. Tight fit bonus: If this bin is the last one that can fit the item, prioritize it.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // 6. Progression scaling: As the stream nears the end, be more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but penalize "near-empty" space that is 
    // too small to fit common items (dead space < 10) and manage bin proliferation.

    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the remaining space is small but > 0, it is likely wasted.
    // We penalize values in the (0, 10) range heavily as they are unusable for the input distribution.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead awareness: If the next item cannot fit in this bin, prioritize 
    // keeping the bin's residual large enough to potentially accommodate it or 
    // keep the space tight to avoid fragmentation.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the fit is excellent.
    // If this is a new bin (bin_residual == bin_capacity), increase cost unless 
    // all existing bins are poor fits.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64 * 0.5);
    }

    // 4. Fitting Density: If this is the only bin that fits the item, reward the choice
    // to avoid the penalty of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // 5. Mean residual alignment: Prefer bins that stay close to the current mean
    // to keep the distribution of residuals uniform across active bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Archetype: Aggressive 2-step lookahead matching.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    if is_new_bin {
        // Penalize opening a new bin heavily unless the current open bins are very full.
        // If mean_residual is low, it means bins are packed well, so opening a new one is costly.
        score += 25.0 + (mean_residual * 0.5) + (open_bins_count as f64 * 0.2);
    } else {
        // Favor placements that leave the bin residual close to the next_item_size.
        // This is a "Best-Fit" variation that tries to create a perfect match for the next item.
        if next_item_size > 0 {
            let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
            score += diff * 0.8;
        }

        // Penalty for creating a "sliver" (very small residual) that is unlikely to fit future items.
        // A residual < 10 is often unusable since the minimum item size is typically around 10.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }

        // If this is the last chance for this bin to be useful (fitting_bins_count == 1),
        // we are more willing to accept a slightly worse fit to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 5.0;
        }

        // Progress-based scaling: As we approach the end of the stream, be more aggressive
        // in filling existing bins to minimize the final bin count.
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 5.0;
    }

    score
}
